import json
import os
import sys
from pathlib import Path
from typing import Optional



# ── Hook templates per target ────────────────────────────────────────────────

def _claude_code_hooks(perseus_cmd: str = "perseus", source: str = ".perseus/context.md") -> dict:
    """Return the hooks dict to merge into .claude/settings.json."""
    cmd = f"{perseus_cmd} render {source}"
    return {
        "SessionStart": [
            {
                "matcher": "",
                "hooks": [
                    {"type": "command", "command": cmd}
                ],
            }
        ],
        "UserPromptSubmit": [
            {
                "matcher": "",
                "hooks": [
                    {"type": "command", "command": cmd}
                ],
            }
        ],
    }


def _cursor_rules_block(version: str) -> str:
    """Return text to append to .cursorrules."""
    return (
        f"\n\n# ── Perseus context (auto-generated, do not edit below this line) ──\n"
        f"# Run `perseus render --format cursorrules` to regenerate.\n"
        f"# Source: .perseus/context.md\n"
        f"# v{version}\n"
    )


def _copilot_header(version: str) -> str:
    """Return header for .github/copilot-instructions.md."""
    return (
        f"<!-- Generated by Perseus v{version} — edit .perseus/context.md instead. -->\n"
        f"<!-- Run `perseus render --format copilot-instructions` to regenerate. -->\n\n"
    )


# ── Target detection and installation ────────────────────────────────────────

def _find_project_root(start: Path | None = None) -> Path:
    """Walk upward from start to find a project root.

    Heuristic: a directory containing .git/, .perseus/, or .claude/.
    Falls back to cwd.
    """
    current = (start or Path.cwd()).resolve()
    for _ in range(10):
        if (current / ".git").exists() or (current / ".perseus").is_dir():
            return current
        if current.parent == current:
            break
        current = current.parent
    return (start or Path.cwd()).resolve()


def _ensure_context_md(workspace: Path, cfg: dict) -> Path:
    """Ensure .perseus/context.md exists; scaffold if missing."""
    perseus_dir = workspace / ".perseus"
    context_file = perseus_dir / "context.md"

    if context_file.exists():
        return context_file

    if not perseus_dir.exists():
        perseus_dir.mkdir(parents=True, exist_ok=True)

    # Scaffold a minimal context.md. The @perseus header is intentionally
    # version-less: pinning a version here goes stale on upgrade (#443). The
    # rendered output already carries the installed version via wrap_rendered,
    # and `perseus doctor` flags an explicit header that drifts from installed.
    content = (
        "@perseus\n"
        "\n"
        "# Project Context\n"
        "\n"
        "@query git branch --show-current\n"
        "@query git log --oneline -5\n"
        "@waypoint\n"
    )
    context_file.write_text(content, encoding="utf-8")
    print(f"  ✓ Created {context_file}")
    return context_file


def _merge_json_file(path: Path, new_data: dict, top_key: str = "hooks") -> bool:
    """Merge new_data into an existing JSON file, deep-merging under top_key."""
    existing: dict = {}
    if path.exists():
        # H-10: Symlink check — refuse to overwrite symlinks
        if path.is_symlink():
            print(
                f"  ⚠ {path} is a symlink; refusing to overwrite for safety.",
                file=sys.stderr,
            )
            return False

        try:
            existing = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, ValueError):
            print(
                f"  ⚠ {path} exists but is not valid JSON; refusing to overwrite.",
                file=sys.stderr,
            )
            return False

        # H-10: JSON validation — refuse to merge into non-dict JSON
        if not isinstance(existing, dict):
            print(
                f"  ⚠ {path} contains non-dict JSON (type={type(existing).__name__}); "
                f"refusing to overwrite.",
                file=sys.stderr,
            )
            return False

    # Deep-merge hooks dicts
    if top_key not in existing:
        existing[top_key] = {}

    for event, hook_list in new_data.items():
        if event not in existing[top_key]:
            existing[top_key][event] = []
        # Avoid exact duplicates
        for hook_entry in hook_list:
            if hook_entry not in existing[top_key][event]:
                existing[top_key][event].append(hook_entry)

    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(existing, indent=2) + "\n", encoding="utf-8")
    return True


# ── Public API ───────────────────────────────────────────────────────────────

def install_target(
    target: str,
    cfg: dict,
    workspace: Path | None = None,
    perseus_cmd: str = "perseus",
    dry_run: bool = False,
) -> dict:
    """Install Perseus hooks for the given target assistant.

    Returns a dict with status info suitable for JSON or human display.
    """
    root = _find_project_root(workspace)
    version = cfg.get("version", "1.0.0")
    source = ".perseus/context.md"

    result: dict = {
        "target": target,
        "workspace": str(root),
        "actions": [],
        "dry_run": dry_run,
    }

    # ── Claude Code ──
    if target == "claude-code":
        # Ensure source exists
        ctx = _ensure_context_md(root, cfg)
        hooks = _claude_code_hooks(perseus_cmd=perseus_cmd)
        settings_path = root / ".claude" / "settings.json"

        result["actions"].append({
            "action": "merge_hooks",
            "file": str(settings_path),
            "events": list(hooks.keys()),
        })

        if not dry_run:
            _merge_json_file(settings_path, hooks)
            print(f"  ✓ Installed SessionStart + UserPromptSubmit hooks → {settings_path}")
            print(f"  → Source: {ctx}")

        result["actions"].append({
            "action": "ensure_source",
            "file": str(ctx),
        })

    # ── Cursor ──
    elif target == "cursor":
        ctx = _ensure_context_md(root, cfg)
        rules_path = root / ".cursorrules"
        block = _cursor_rules_block(version)

        result["actions"].append({
            "action": "append_block",
            "file": str(rules_path),
        })

        if not dry_run:
            existing = ""
            if rules_path.exists():
                existing = rules_path.read_text(encoding="utf-8")
            # Only append the block once
            if "Perseus context (auto-generated)" not in existing:
                rules_path.write_text(existing + block, encoding="utf-8")
                print(f"  ✓ Added Perseus block → {rules_path}")
            else:
                print(f"  • Perseus block already present in {rules_path}")

        result["actions"].append({
            "action": "ensure_source",
            "file": str(ctx),
        })

    # ── Gemini CLI ──
    elif target == "gemini-cli":
        ctx = _ensure_context_md(root, cfg)
        result["actions"].append({
            "action": "note",
            "text": (
                "Gemini CLI reads GEMINI_SYSTEM_MD environment variable. "
                "Set it to the Perseus-rendered output:\n"
                f"  export GEMINI_SYSTEM_MD=\"$(perseus render {source})\"\n"
                "Or add this to your shell profile."
            ),
        })
        if not dry_run:
            print(f"  ✓ Source ready: {ctx}")
            print(f"  → Add to your shell profile:")
            print(f'    export GEMINI_SYSTEM_MD="$(perseus render {source})"')

        result["actions"].append({
            "action": "ensure_source",
            "file": str(ctx),
        })

    # ── GitHub Copilot ──
    elif target == "copilot":
        ctx = _ensure_context_md(root, cfg)
        copilot_dir = root / ".github"
        copilot_file = copilot_dir / "copilot-instructions.md"

        result["actions"].append({
            "action": "write_or_update",
            "file": str(copilot_file),
        })

        if not dry_run:
            copilot_dir.mkdir(parents=True, exist_ok=True)
            header = _copilot_header(version)
            if not copilot_file.exists() or "Generated by Perseus" not in copilot_file.read_text(encoding="utf-8"):
                copilot_file.write_text(
                    header + f"Run `perseus render --format copilot-instructions` to populate this file.\n",
                    encoding="utf-8",
                )
                print(f"  ✓ Created {copilot_file}")
            else:
                print(f"  • Perseus header already present in {copilot_file}")

        result["actions"].append({
            "action": "ensure_source",
            "file": str(ctx),
        })

    else:
        print(f"  ✗ Unknown target: {target}", file=sys.stderr)
        print(f"    Supported: claude-code, cursor, gemini-cli, copilot", file=sys.stderr)
        result["error"] = f"Unknown target: {target}"
        return result

    # ── Render initial output ──
    if not dry_run and target in FORMAT_TARGETS:
        # Suggest the user run render
        fmt = {
            "claude-code": "claude-md",
            "cursor": "cursorrules",
            "gemini-cli": "claude-md",  # closest
            "copilot": "copilot-instructions",
        }.get(target, "agents-md")

        print(f"  → Run `perseus render {source} --format {fmt}` to populate the target file.")
        print(f"  → Or `perseus render {source} --format {fmt} -o {root / FORMAT_TARGETS[fmt].default_output}`")

    return result
# ─────────────────────────────── Health ──────────────────────────────────────

def _health_collect(cfg: dict, workspace: Path) -> list[str]:
    """Run deterministic maintenance heuristics. Returns markdown lines."""
    hcfg = cfg.get("health", {})
    stale_days = int(hcfg.get("stale_checkpoint_days", 7))
    dup_window = int(hcfg.get("duplicate_checkpoint_window", 5))
    ctx_warn = int(hcfg.get("context_line_warning", 400))
    completed_days = int(hcfg.get("include_completed_tasks_older_than_days", 14))

    lines: list[str] = []

    # 1. Stale checkpoints
    cp_files = _list_checkpoint_files(cfg)
    stale_threshold = time.time() - stale_days * 86400
    stale = []
    for fp in cp_files:
        cp = _load_checkpoint_file(fp) or {}
        w = str(cp.get("written", ""))
        try:
            dt = datetime.fromisoformat(w)
            if dt.timestamp() < stale_threshold:
                stale.append((fp.name, _human_age(w)))
        except Exception:
            continue
    if stale:
        lines.append(f"### Stale Checkpoints (older than {stale_days} days)")
        for name, age in stale[:10]:
            lines.append(f"- `{name}` — {age}")
        if len(stale) > 10:
            lines.append(f"- _… and {len(stale) - 10} more_")
        lines.append("")

    # 2. Duplicate / near-duplicate checkpoints
    window = cp_files[:dup_window]
    seen: dict[tuple, list[str]] = {}
    for fp in window:
        cp = _load_checkpoint_file(fp) or {}
        key = (str(cp.get("task", "")).strip(), str(cp.get("status", "")).strip(), str(cp.get("next", "")).strip())
        seen.setdefault(key, []).append(fp.name)
    dups = [(k, v) for k, v in seen.items() if len(v) > 1]
    if dups:
        lines.append(f"### Duplicate Checkpoints (in last {dup_window})")
        for (task, status, nxt), names in dups:
            lines.append(f"- **{task or '(no task)'}** — appears {len(names)}× with same status/next:")
            for n in names:
                lines.append(f"  - `{n}`")
        lines.append("")

    # 3. Large context source file
    ctx_path = workspace / ".perseus" / "context.md"
    if ctx_path.exists():
        try:
            n_lines = ctx_path.read_text(errors="replace", encoding="utf-8").count("\n") + 1
            if n_lines > ctx_warn:
                lines.append("### Context Source Size")
                lines.append(
                    f"- `{ctx_path}` is **{n_lines} lines** (warning threshold: {ctx_warn})."
                    " Consider extracting sections into separate `@include`d files."
                )
                lines.append("")
        except Exception:
            pass

    # 4. Old completed tasks in Agora
    tasks_dir = _get_tasks_dir(workspace, cfg)
    if tasks_dir.exists():
        completed_threshold = time.time() - completed_days * 86400
        old_done = []
        for task_file in sorted(tasks_dir.glob("task-*.md")):
            try:
                fm, _ = _load_task_file(task_file)
            except Exception:
                continue
            if str(fm.get("status", "")).lower() != "completed":
                continue
            closed = str(fm.get("closed", "") or "")
            try:
                dt = datetime.fromisoformat(closed)
                if dt.timestamp() < completed_threshold:
                    old_done.append((task_file.name, closed))
            except Exception:
                continue
        if old_done:
            lines.append(f"### Old Completed Tasks (closed > {completed_days} days ago)")
            for name, closed in old_done[:10]:
                lines.append(f"- `{name}` — closed {closed} (consider archiving)")
            lines.append("")

    if not lines:
        lines.append("_All clear — no maintenance suggestions._")

    return lines


def _health_report(cfg: dict, workspace: Path) -> str:
    """Render full health report as markdown."""
    header = f"# Perseus Health Report\n\n**Workspace:** `{workspace}`  \n**Generated:** {datetime.now().astimezone().strftime('%Y-%m-%d %H:%M %Z')}\n\n---\n\n"
    body = "\n".join(_health_collect(cfg, workspace))
    return header + body + "\n"


def cmd_health(args, cfg):
    ws = Path(getattr(args, "workspace", None) or os.getcwd()).expanduser().resolve()
    print(_health_report(cfg, ws))


def resolve_health(args_str: str, cfg: dict, workspace: Path | None = None) -> str:
    """@health [section-only] — embed maintenance suggestions inline."""
    ws = (workspace or Path.cwd()).expanduser().resolve()
    return "\n".join(_health_collect(cfg, ws))


# ─────────────────────────────── Doctor ──────────────────────────────────────

def _find_version() -> str:
    """Read version from VERSION file in repo root if present, else use baked-in.

    #644: only honor a VERSION file that sits beside a repo marker (.git or
    scripts/build.py). The walk covers ALL ancestors of the artifact, so an
    unrelated VERSION file anywhere above a deployed perseus.py used to
    silently override the baked-in version reported by --version and MCP
    serverInfo — wrong version strings in support tickets are expensive.
    """
    start = Path(__file__).resolve().parent
    for p in [start] + list(start.parents):
        candidate = p / "VERSION"
        if candidate.exists() and (
            (p / ".git").exists() or (p / "scripts" / "build.py").exists()
        ):
            return candidate.read_text(encoding="utf-8").strip()
    return _PERSEUS_VERSION  # fallback to build-time injected literal

_PERSEUS_VERSION = "1.0.27"  # replaced at build time by scripts/build.py (see VERSION file)
_PERSEUS_VERSION = _find_version()


class DoctorResult(NamedTuple):
    id: str
    status: str        # "ok" | "warn" | "error"
    label: str
    value: str
    remediation: str   # "" if none
    details: dict | None = None


def _doctor_check_config(cfg: dict, workspace: Path) -> DoctorResult:
    """Check that config parses as valid YAML."""
    config_path = PERSEUS_HOME / "config.yaml"
    if config_path.exists():
        try:
            with open(config_path, encoding='utf-8') as f:
                yaml.safe_load(f)
            return DoctorResult("config_parses", "ok", "config parses", str(config_path), "")
        except Exception as exc:
            return DoctorResult("config_parses", "error", "config parses", str(exc),
                                f"Fix YAML syntax in {config_path}")
    # No config file — using defaults, that's fine
    return DoctorResult("config_parses", "ok", "config parses", "(defaults — no config file)", "")


def _doctor_check_context_file(cfg: dict, workspace: Path) -> DoctorResult:
    """Check that the workspace has a .perseus/context.md (or .hermes.md)."""
    for name in (".perseus/context.md", ".hermes.md"):
        p = workspace / name
        if p.exists():
            return DoctorResult("workspace_context_file", "ok", "workspace context file", str(p), "")
    return DoctorResult("workspace_context_file", "warn", "workspace context file",
                        "not found (.perseus/context.md or .hermes.md)",
                        "Run `perseus init` to scaffold a context file")


def _doctor_check_render_shell(cfg: dict, workspace: Path) -> DoctorResult:
    """Informational: is @query shell execution enabled?"""
    enabled = cfg.get("render", {}).get("allow_query_shell", False)
    val = f"allow_query_shell={str(enabled).lower()}"
    return DoctorResult("render_shell", "ok", "render: shell execution", val, "")


def _doctor_check_render_outside_workspace(cfg: dict, workspace: Path) -> DoctorResult:
    """Informational: is @read outside workspace allowed?"""
    allowed = cfg.get("render", {}).get("allow_outside_workspace", False)
    val = f"allow_outside_workspace={str(allowed).lower()}"
    return DoctorResult("render_outside_workspace", "ok", "render: outside-workspace reads", val, "")


def _doctor_check_latest_checkpoint(cfg: dict, workspace: Path) -> DoctorResult:
    """Check recency of the latest checkpoint."""
    cp_dir = PERSEUS_HOME / "checkpoints"
    if not cp_dir.is_dir():
        return DoctorResult("latest_checkpoint_age", "warn", "latest checkpoint",
                            "no checkpoints directory", "Run `perseus checkpoint --task '...'`")
    yamls = sorted(cp_dir.glob("2*.yaml"), reverse=True)
    if not yamls:
        return DoctorResult("latest_checkpoint_age", "warn", "latest checkpoint",
                            "no checkpoints found", "Run `perseus checkpoint --task '...'`")
    try:
        ts_str = yamls[0].stem[:19]  # 2026-05-18T0828
        ts = datetime.strptime(ts_str, "%Y-%m-%dT%H%M")
        age = datetime.now() - ts
        age_days = age.days
        hours = age.seconds // 3600
        minutes = (age.seconds % 3600) // 60
        if age_days > 0:
            age_str = f"{age_days}d {hours}h ago"
        else:
            age_str = f"{hours}h {minutes}m ago"
        if age_days > 30:
            return DoctorResult("latest_checkpoint_age", "error", "latest checkpoint",
                                age_str, "Run `perseus checkpoint --task '...'` — checkpoint is very stale")
        if age_days > 7:
            return DoctorResult("latest_checkpoint_age", "warn", "latest checkpoint",
                                age_str, "Consider running `perseus checkpoint --task '...'`")
        return DoctorResult("latest_checkpoint_age", "ok", "latest checkpoint", age_str, "")
    except Exception:
        return DoctorResult("latest_checkpoint_age", "ok", "latest checkpoint", str(yamls[0].name), "")


def _doctor_check_vault(cfg: dict, workspace: Path) -> DoctorResult:
    """Check Perseus Vault narrative existence and size."""
    mem_cfg = cfg.get("memory", {})
    narrative = _vault_memory_path(workspace, cfg)
    if not narrative.exists():
        return DoctorResult("vault_narrative", "warn", f"{MEMORY_BRAND} narrative",
                            "not found", "Memory will auto-create on next render with @memory")
    lines = narrative.read_text(errors="replace", encoding="utf-8").splitlines()
    max_lines = mem_cfg.get("max_narrative_lines", 300)
    line_count = len(lines)
    val = f"{line_count} lines"
    if line_count > max_lines:
        return DoctorResult("vault_narrative", "warn", f"{MEMORY_BRAND} narrative",
                            f"{val} (exceeds max_narrative_lines={max_lines})",
                            "Consider pruning old entries from the narrative")
    return DoctorResult("vault_narrative", "ok", f"{MEMORY_BRAND} narrative", val, "")


def _doctor_check_federation(cfg: dict, workspace: Path) -> DoctorResult:
    """Check federation subscription health."""
    mem_cfg = cfg.get("memory", {})
    manifest_path = _federation_manifest_path(cfg)
    if not manifest_path.exists():
        return DoctorResult("federation_subscriptions", "ok", "federation",
                            "no subscriptions configured", "")
    try:
        with open(manifest_path, encoding='utf-8') as f:
            manifest = yaml.safe_load(f) or {}
        if not isinstance(manifest, dict):
            raise ValueError(f"manifest is not a mapping (got {type(manifest).__name__})")
        if not isinstance(manifest.get("subscriptions", []), list):
            raise ValueError("subscriptions must be a list")
    except Exception as exc:
        return DoctorResult("federation_subscriptions", "error", "federation",
                            f"manifest unreadable: {exc}", f"Fix {manifest_path}")
    subs = manifest.get("subscriptions", [])
    if not subs:
        return DoctorResult("federation_subscriptions", "ok", "federation",
                            "no subscriptions", "")
    stale = []
    stale_threshold_days = mem_cfg.get("federation_stale_threshold_days", 7)
    for sub_entry in subs:
        alias = sub_entry.get("alias", "?")
        narrative, err = _resolve_subscription_narrative(sub_entry, cfg)
        if err or narrative is None:
            stale.append(f"{alias} (unavailable)")
            continue
        if narrative.exists():
            import os as _os
            mtime = datetime.fromtimestamp(_os.path.getmtime(narrative))
            age = (datetime.now() - mtime).days
            if age > stale_threshold_days:
                stale.append(f"{alias} ({age}d old)")
    if stale:
        return DoctorResult("federation_subscriptions", "warn", "federation",
                            f"{len(subs)} subs, stale: {', '.join(stale)}",
                            "Run `perseus memory federation pull`")
    return DoctorResult("federation_subscriptions", "ok", "federation",
                        f"{len(subs)} subscriptions, all fresh", "")


def _doctor_check_guide_log(cfg: dict, workspace: Path) -> DoctorResult:
    """Check Guide log readability."""
    log_path = _guide_log_path()
    if not log_path.exists():
        return DoctorResult("guide_log_readable", "ok", "Guide log",
                            "no log file (will be created on first suggest)", "")
    try:
        count = 0
        with open(log_path, encoding='utf-8') as f:
            for lineno, line in enumerate(f, start=1):
                line = line.strip()
                if not line:
                    continue
                data = json.loads(line)
                if not isinstance(data, dict):
                    raise ValueError(f"line {lineno}: entry is not an object")
                count += 1
        return DoctorResult("guide_log_readable", "ok", "Guide log",
                            f"{count} entries", "")
    except Exception as exc:
        return DoctorResult("guide_log_readable", "error", "Guide log",
                            str(exc), f"Fix JSONL in {log_path}")


def _doctor_check_guide_legacy_pythia(cfg: dict, workspace: Path) -> DoctorResult:
    """Removal-gate warning: legacy `pythia` config/log usage must be migrated
    before LEGACY_PYTHIA_REMOVAL_DATE — after that the bridge is removed."""
    if not LEGACY_GUIDE_CONFIG_KEY and not LEGACY_GUIDE_LOG_NAME:
        return DoctorResult("guide_legacy_pythia", "ok", "Guide legacy pythia", "removed", "")
    removal = LEGACY_PYTHIA_REMOVAL_DATE
    # loaded cfg is already normalized (pythia merged into guide) — scan the
    # raw config files for a literal `pythia:` block
    legacy_cfg = False
    for cfg_file in (PERSEUS_HOME / "config.yaml", workspace / ".perseus" / "config.yaml"):
        try:
            if cfg_file.exists() and re.search(r"^\s*pythia\s*:", cfg_file.read_text(errors="replace", encoding="utf-8"), re.M):
                legacy_cfg = True
        except Exception:
            pass
    legacy_log = (PERSEUS_HOME / LEGACY_GUIDE_LOG_NAME).exists()
    if legacy_cfg or legacy_log:
        return DoctorResult(
            "guide_legacy_pythia", "warning", "Guide legacy pythia",
            f"legacy 'pythia' config/log in use — migrate to 'guide' before {removal} (then removed)",
            "Rename the `pythia:` config block to `guide:`; the log migrates automatically",
        )
    return DoctorResult("guide_legacy_pythia", "ok", "Guide legacy pythia", "none in use", "")


def _doctor_check_serve_loopback(cfg: dict, workspace: Path) -> DoctorResult:
    """Informational: confirm serve defaults to loopback."""
    bind = _serve_bind_host(cfg)
    if _serve_is_loopback(bind):
        return DoctorResult("serve_loopback_only", "ok", "serve loopback default",
                            bind, "")
    return DoctorResult("serve_loopback_only", "warn", "serve loopback default",
                        f"bind={bind} (not loopback)",
                        "Set serve.bind_host to 127.0.0.1 unless intentional")


def _doctor_check_registry(cfg: dict, workspace: Path) -> DoctorResult:
    """Validate DIRECTIVE_REGISTRY consistency."""
    issues = []
    for name, spec in DIRECTIVE_REGISTRY.items():
        if spec.kind == "inline" and not callable(spec.resolver):
            issues.append(f"{name}: inline but no callable resolver")
        if (spec.executes_shell or spec.mutates_state) and spec.safe_for_hover:
            issues.append(f"{name}: unsafe but safe_for_hover=True")
    if issues:
        return DoctorResult("directive_registry", "error", "directive registry",
                            "; ".join(issues), "Fix DIRECTIVE_REGISTRY entries")
    return DoctorResult("directive_registry", "ok", "directive registry",
                        f"{len(DIRECTIVE_REGISTRY)} directives registered", "")


def _doctor_check_mcp(cfg: dict, workspace: Path) -> DoctorResult:
    """Check MCP server readiness — registry and tool count."""
    try:
        tools = _get_all_mcp_tools(cfg)
        count = len(tools)
        if count == 0:
            return DoctorResult("mcp_server", "warn", "mcp_server", "0 tools available", "Check DIRECTIVE_REGISTRY and config")
        return DoctorResult("mcp_server", "ok", "mcp_server", f"{count} MCP tools available", "")
    except Exception as exc:
        return DoctorResult("mcp_server", "error", "mcp_server", str(exc), "Check mcp.py")


def _doctor_check_vault_index(_cfg: dict, _workspace: Path) -> DoctorResult:
    """Check Perseus Vault FTS5 index health — existence, population, orphans."""
    try:
        stats = _vault_index_stats(_cfg)
        if not stats["available"]:
            return DoctorResult("vault_fts_index", "warn", f"{MEMORY_BRAND} FTS index",
                                "index not available (vault may be empty)",
                                "Add memory files to trigger indexing, or run `perseus memory index rebuild`")

        doc_count = stats["doc_count"]
        file_count = stats["indexed_files"]
        index_path = stats["index_path"]

        # Orphan check: files in index that no longer exist in vault. The
        # vault_files schema column is "path" (see vault_index.py), not
        # "file_path" -- a stale query name here previously made this check a
        # permanent silent no-op via the bare except below (always 0 orphans,
        # even with a moved/deleted vault).
        orphans = 0
        orphan_check_failed = False
        try:
            conn = _vault_open_index(_cfg)
            if conn:
                rows = conn.execute("SELECT path FROM vault_files").fetchall()
                for (fp,) in rows:
                    if not Path(fp).exists():
                        orphans += 1
        except sqlite3.OperationalError:
            # Schema drift (e.g. a renamed/missing column) -- surface it
            # instead of silently reporting a healthy 0.
            orphan_check_failed = True

        parts = [f"{doc_count} docs, {file_count} files tracked"]
        if orphan_check_failed:
            parts.append("orphan check failed (index schema mismatch)")
            return DoctorResult("vault_fts_index", "warn", f"{MEMORY_BRAND} FTS index",
                                ", ".join(parts),
                                "Run `perseus memory index rebuild` to recreate the index")
        if orphans > 0:
            parts.append(f"{orphans} orphaned entries")
            return DoctorResult("vault_fts_index", "warn", f"{MEMORY_BRAND} FTS index",
                                ", ".join(parts),
                                f"{orphans} orphaned entries — run `perseus memory index rebuild`")
        if doc_count == 0:
            return DoctorResult("vault_fts_index", "warn", f"{MEMORY_BRAND} FTS index",
                                "index exists but is empty",
                                "Run `perseus memory index rebuild`")
        return DoctorResult("vault_fts_index", "ok", f"{MEMORY_BRAND} FTS index", ", ".join(parts), "")
    except Exception as exc:
        return DoctorResult("vault_fts_index", "error", f"{MEMORY_BRAND} FTS index", str(exc), "Check vault_index.py")


def _doctor_check_cache_writable(cfg: dict, workspace: Path) -> DoctorResult:
    """Check whether the render cache directory is writable."""
    cache_dir = Path(cfg.get("render", {}).get("cache_dir", str(PERSEUS_HOME / "cache")))
    try:
        cache_dir.mkdir(parents=True, exist_ok=True)
        test_file = cache_dir / ".doctor_test"
        test_file.write_text("ok", encoding="utf-8")
        test_file.unlink()
        # Count cache entries
        entries = len([f for f in cache_dir.iterdir() if f.suffix == ".json"])
        return DoctorResult("cache_writable", "ok", "Cache",
                           f"{entries} entries, writable", "")
    except Exception as exc:
        return DoctorResult("cache_writable", "error", "Cache",
                           f"not writable: {exc}",
                           f"Check permissions on {cache_dir}")


def _doctor_check_sessions(cfg: dict, workspace: Path) -> DoctorResult:
    """Check whether the sessions store is accessible."""
    sessions_dir = SESSIONS_DIR  # from config.py
    sessions_path = Path(sessions_dir)
    if not sessions_path.exists():
        return DoctorResult("sessions_store", "ok", "Session store",
                           "directory does not exist (will be created on first write)", "")
    try:
        session_files = list(sessions_path.glob("*.json"))
        return DoctorResult("sessions_store", "ok", "Session store",
                           f"{len(session_files)} sessions", "")
    except Exception as exc:
        return DoctorResult("sessions_store", "warn", "Session store",
                           str(exc), "Check SESSIONS_DIR permissions")


# The only supported memory binary is the Perseus Vault executable.
_MEMORY_BINARY_NAMES = ("perseus-vault",)
_KNOWN_VAULT_PATHS = [
    os.path.join(prefix, name)
    for name in _MEMORY_BINARY_NAMES
    for prefix in (
        "/usr/local/bin",
        os.path.expanduser("~/.local/bin"),
        os.path.expanduser("~/.cargo/bin"),
        "/usr/bin",
    )
]

# Version-bound remediation shown when the memory connector is configured but
# the binary is absent (#663). Perseus does not download or execute remote code.
MEMORY_INSTALL_REMEDIATION = (
    "Install Perseus Vault from a verified release, then re-run `perseus doctor`. "
    "Release: https://github.com/Perseus-Computing-LLC/perseus-vault/releases/tag/v2.23.2 . "
    "The x86_64 Linux archive SHA-256 is "
    "7143709aa6c9c29128e5daae47c13ddcc6ec56b35c7a605726b51f635309998e; "
    "verify it before extraction. Other platforms and provenance are on the release page. "
    "You can wire the connector with `perseus quickstart --with-memory`."
)


def _find_vault_binary(configured_command: list[str]) -> str | None:
    """Search common paths for the memory (Perseus Vault) binary.

    Returns the first found absolute path, or None if not found.
    Used by doctor/quickstart to surface a clear suggestion when the memory
    connector is configured but the binary isn't on PATH (#227, #663).
    """
    binary_name = configured_command[0] if configured_command else "perseus-vault"

    # Check if the configured binary is already resolvable via PATH
    import shutil as _shutil
    resolved = _shutil.which(binary_name)
    if resolved:
        return resolved

    candidates = list(_KNOWN_VAULT_PATHS)
    # Development discovery is limited to the canonical project directory.
    if os.environ.get("PERSEUS_DEV_VAULT_BUILD") == "1":
        try:
            cwd = Path.cwd()
            src_dir = cwd / "perseus-vault"
            candidates.append(str(src_dir / "target" / "release" / "perseus-vault"))
            candidates.append(str(src_dir / "target" / "debug" / "perseus-vault"))
        except Exception:
            pass

    for p in candidates:
        expanded = Path(p).expanduser()
        if expanded.is_file() and os.access(expanded, os.X_OK):
            return str(expanded)

    return None


def _doctor_check_vault_bridge(cfg: dict, workspace: Path) -> DoctorResult:
    """Check vault connectivity and binary discovery (#226, #227).

    When vault.enabled is true, this check:
      1. Searches common paths for the vault binary (#227)
      2. Attempts MCP handshake + perseus_vault_health tool call (#226)
      3. Surfaces a clear warning (not silent Vault fallback) if unreachable
    """
    vault_cfg = _resolve_vault_config(cfg)
    enabled = bool(vault_cfg.get("enabled", True))

    if not enabled:
        return DoctorResult("vault_connectivity", "ok", MEMORY_BRAND,
                           "disabled", "")

    command = list(vault_cfg.get("command", ["perseus-vault", "serve"]))
    binary_name = command[0] if command else "perseus-vault"

    # Step 1: Auto-discover binary if not on PATH (#227)
    binary_path = _find_vault_binary(command)
    if binary_path is None:
        # #663: the connector is configured (enabled) but the memory binary is
        # absent, so memory would be silently empty. Warn clearly with
        # copy-paste remediation instead of leaving the user to discover it.
        return DoctorResult("vault_connectivity", "warn", f"{MEMORY_BRAND} binary",
                           f"configured but not found: '{binary_name}' "
                           "(searched PATH + known locations) — persistent memory "
                           "will be empty until it is installed",
                           MEMORY_INSTALL_REMEDIATION)
    if binary_path != binary_name:
        # Found at a non-default path — update command for the connection attempt
        command[0] = binary_path

    # Step 2: Attempt MCP handshake + health check (#226)
    try:
        # Build a temporary connector with the discovered binary path. Write
        # under the canonical `perseus_vault:` key (#662) so it wins in
        # Resolve the canonical Perseus Vault block before validating defaults.
        test_cfg = dict(cfg)
        test_cfg["perseus_vault"] = dict(vault_cfg)
        test_cfg["perseus_vault"]["command"] = command

        connector = VaultConnector(test_cfg)
        if connector.available:
            # Run health check
            healthy, status = connector.health_check()
            if healthy:
                # Try to get version from health check response
                version_info = ""
                raw_result, _ = connector._client.call_tool("perseus_vault_health", {}) if connector._client else (None, None)
                if raw_result and isinstance(raw_result, dict):
                    ver = raw_result.get("version", "")
                    db_path = raw_result.get("db_path", "")
                    if ver:
                        version_info = f" (v{ver})"
                    if db_path:
                        version_info += f" db: {db_path}"
                connector.close()
                extra = f" (binary: {binary_path})" if binary_path != binary_name else ""
                return DoctorResult("vault_connectivity", "ok", MEMORY_BRAND,
                                   f"connected + healthy{version_info}{extra}", "")
            else:
                connector.close()
                return DoctorResult("vault_connectivity", "warn", MEMORY_BRAND,
                                   f"connected but health check failed: {status}",
                                   "Check the Perseus Vault server status")
        else:
            err = connector.status
            connector.close()
            return DoctorResult("vault_connectivity", "warn", MEMORY_BRAND,
                               f"unreachable: {err}",
                               "Check Perseus Vault is running or install it")
    except Exception as exc:
        return DoctorResult("vault_connectivity", "error", MEMORY_BRAND,
                           str(exc),
                           "Verify the perseus-vault binary and the `perseus_vault.command` in config.yaml")


def _doctor_check_ledger_metering(cfg: dict, workspace: Path) -> DoctorResult:
    """Check supported Ledger runtime wiring without exposing secrets."""
    p = cfg.get("ledger") if isinstance(cfg, dict) else None
    if not isinstance(p, dict):
        p = cfg.get("plutus")  # legacy pre-2026-08-09 key, still honored
    if not isinstance(p, dict) or not p.get("enabled"):
        return DoctorResult("ledger_metering", "ok", "Ledger metering", "disabled", "")
    if not (p.get("endpoint") or p.get("db_path")):
        return DoctorResult(
            "ledger_metering", "error", "Ledger metering",
            "enabled but no endpoint or db_path is configured",
            "Set ledger.endpoint or ledger.db_path in config.yaml (legacy plutus.* honored)",
        )
    try:
        metering_status = globals().get("metering_status")
        if metering_status is None:
            from .metering import metering_status
        status = metering_status(cfg)
        if status.get("degraded"):
            return DoctorResult(
                "ledger_metering", "warn", "Ledger metering",
                f"DEGRADED: {status.get('dropped_events', 0)} dropped, "
                f"{status.get('coverage_pct', 0):.1f}% baseline coverage",
                "Inspect metering-status.json and Ledger reachability",
            )
        return DoctorResult(
            "ledger_metering", "ok", "Ledger metering",
            f"enabled, {status.get('coverage_pct', 0):.1f}% baseline coverage",
            "",
        )
    except Exception as exc:
        return DoctorResult("ledger_metering", "error", "Ledger metering", str(exc),
                           "Verify the installed Perseus/Ledger integration")


def _doctor_check_version_header(cfg: dict, workspace: Path) -> DoctorResult:
    """Check if the @perseus version header in context.md matches installed version."""
    ctx_path = workspace / ".perseus" / "context.md"
    if not ctx_path.exists():
        return DoctorResult("version_header", "ok", "@perseus version header",
                           "no context.md found (skipped)", "")
    try:
        first_line = ctx_path.read_text(errors="replace", encoding="utf-8").split("\n")[0].strip()
    except Exception:
        return DoctorResult("version_header", "ok", "@perseus version header",
                           "could not read context.md", "")
    
    installed_ver = _PERSEUS_VERSION
    v_match = re.match(r'@perseus\s+v?([\d.]+)', first_line, re.IGNORECASE)
    if not v_match:
        # A version-less @perseus header is the recommended form (#443): there is
        # nothing to go stale, and the rendered output already carries the
        # installed version. Only flag a line that isn't a @perseus header at all.
        if re.match(r'@perseus\b', first_line, re.IGNORECASE):
            return DoctorResult("version_header", "ok", "@perseus version header",
                               f"version-less @perseus header (resolves to installed v{installed_ver})", "")
        return DoctorResult("version_header", "warn", "@perseus version header",
                           f"no @perseus header found in context.md (first line: {first_line[:60]})",
                           "Start .perseus/context.md with a @perseus line")

    header_ver = v_match.group(1)

    if header_ver == installed_ver:
        return DoctorResult("version_header", "ok", "@perseus version header",
                           f"v{header_ver} matches installed v{installed_ver}", "")
    else:
        return DoctorResult("version_header", "warn", "@perseus version header",
                           f"context.md pins v{header_ver} but perseus is v{installed_ver}",
                           f"Drop the version from the @perseus header so it can't go stale, or update it to v{installed_ver}")


def _doctor_check_stale_shim(cfg: dict, workspace: Path) -> DoctorResult:
    """Check for stale ~/.local/bin/perseus shim from old install.sh (#252)."""
    shim_path = os.path.expanduser("~/.local/bin/perseus")
    share_path = os.path.expanduser("~/.local/share/perseus/perseus.py")
    
    if not os.path.isfile(shim_path):
        return DoctorResult("stale_shim", "ok", "Legacy shim",
                           "no shim at ~/.local/bin/perseus", "")
    
    # Distinguish a legit pip install (a console entry-point script, which may
    # be reached via a stable symlink) from an old install.sh shim. A pip
    # entry-point wrapper contains `from perseus import main`; a legacy shim is
    # a /bin/sh wrapper that execs a bundled perseus.py, or points at the old
    # ~/.local/share/perseus/perseus.py. Only the latter is stale (#252). A bare
    # symlink to the pip console script is the recommended stable-pointer setup
    # and must NOT be flagged (previously any symlink always warned).
    is_shim = False
    try:
        target = os.path.realpath(shim_path)
        with open(target, encoding='utf-8') as f:
            head = f.read(4096)
        is_pip_entrypoint = ('from perseus import' in head) or ('import perseus' in head)
        looks_like_sh_shim = head.startswith('#!/bin/sh') or head.startswith('#!/usr/bin/env sh')
        refs_legacy_bundle = ('/.local/share/perseus/perseus.py' in head)
        if not is_pip_entrypoint and (looks_like_sh_shim or refs_legacy_bundle):
            is_shim = True
    except Exception:
        pass
    
    if is_shim or os.path.isfile(share_path):
        return DoctorResult("stale_shim", "warn", "Legacy shim",
                           f"old install.sh shim detected at {shim_path}",
                           "Remove legacy shim: rm -f ~/.local/bin/perseus ~/.local/share/perseus/perseus.py && pip install --upgrade perseus-ctx")
    
    return DoctorResult("stale_shim", "ok", "Legacy shim",
                       "shim at ~/.local/bin/perseus looks current", "")


def _read_perseus_module_version(path: str) -> str:
    """Extract the build-time ``_PERSEUS_VERSION`` literal from a perseus.py copy.

    Reads only the head of the file and matches the first assignment of the
    form ``_PERSEUS_VERSION = "X.Y.Z"`` (the literal replaced at build time by
    scripts/build.py). Returns ``"?"`` when the file can't be read or no
    version literal is found. We deliberately parse the source text rather than
    importing the module — importing a *stale* copy would shadow the active one
    and is far more expensive/dangerous than a read.
    """
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            head = f.read(8192)
    except Exception:
        return "?"
    m = re.search(r'''_PERSEUS_VERSION\s*=\s*["']([\d]+\.[\d]+\.[\d]+[^"']*)["']''', head)
    return m.group(1) if m else "?"


def _version_sort_key(ver: str):
    """Sort key: newest version first among non-active installs."""
    parts = re.findall(r"\d+", ver or "")
    nums = tuple(int(p) for p in parts[:3]) if parts else (0,)
    # Negate so that higher versions sort earlier within the non-active group.
    return tuple(-n for n in nums)


def _discover_perseus_installs() -> list[dict]:
    """Find every installed ``perseus.py`` copy across Python minor versions.

    ``perseus`` installs as a single top-level module into a per-Python-minor
    site-packages dir. Upgrading the interpreter (e.g. 3.13 -> 3.14) and
    reinstalling with ``pip install --user`` leaves the OLD copy behind in the
    previous minor's site-packages (#734). The ``~/.local/bin/perseus`` symlink
    points at the newest, so the active binary is correct, but the stale copies
    are a latent footgun that show up as historical-residue warnings whose
    source is invisible to ``perseus --version`` (which only reports the active
    install).

    Scans both macOS and Linux ``--user`` layouts plus any site-packages on
    ``sys.path`` (covers venvs / system installs). Returns one dict per DISTINCT
    real path: ``{"path", "version", "active"}``, sorted with the active install
    first, then by version descending.
    """
    import glob as _glob

    home = os.path.expanduser("~")
    patterns = [
        # macOS `pip install --user` (per-minor):
        os.path.join(home, "Library", "Python", "*", "lib", "python", "site-packages", "perseus.py"),
        # Linux `pip install --user` (per-minor):
        os.path.join(home, ".local", "lib", "python*", "site-packages", "perseus.py"),
        # Legacy install.sh bundle location:
        os.path.join(home, ".local", "share", "perseus", "perseus.py"),
    ]
    candidates: set[str] = set()
    for pat in patterns:
        for hit in _glob.glob(pat):
            candidates.add(hit)
    # Also probe every site-packages currently on sys.path (venvs, system).
    for entry in list(sys.path):
        if not entry:
            continue
        cand = os.path.join(entry, "perseus.py")
        if os.path.isfile(cand):
            candidates.add(cand)

    try:
        active_real = os.path.realpath(os.path.abspath(__file__))
    except Exception:
        active_real = ""
    # Always represent the active install itself, even if it lives outside the
    # scanned site-packages layouts (e.g. a repo checkout or an editable install).
    if active_real and os.path.isfile(active_real):
        candidates.add(active_real)

    by_real: dict[str, dict] = {}
    for path in candidates:
        try:
            if not os.path.isfile(path):
                continue
            real = os.path.realpath(path)
        except Exception:
            continue
        if real in by_real:
            continue
        by_real[real] = {
            "path": path,
            "version": _read_perseus_module_version(real),
            "active": (real == active_real),
        }

    installs = list(by_real.values())
    # Put active first, then highest version among the rest.
    installs.sort(key=lambda d: (0 if d["active"] else 1, _version_sort_key(d["version"])))
    return installs


def _doctor_check_duplicate_installs(cfg: dict, workspace: Path) -> DoctorResult:
    """Warn when multiple perseus.py copies exist across Python minors (#734).

    The active binary is correct (the ~/.local/bin/perseus symlink resolves to
    the newest), but stale copies in older Python minors' site-packages emit
    historical-residue warnings whose origin is invisible to `perseus
    --version`. Surface the drift (never auto-delete) so the active-vs-stale
    split is obvious and removable.
    """
    installs = _discover_perseus_installs()

    if len(installs) <= 1:
        loc = installs[0]["path"] if installs else "(active install only)"
        return DoctorResult("duplicate_installs", "ok", "Duplicate installs",
                            f"single install ({loc})", "")

    # More than one distinct copy on disk — flag the stale ones.
    active = next((d for d in installs if d["active"]), None)
    active_ver = active["version"] if active else "?"
    stale = [d for d in installs if not d["active"]]
    stale_desc = ", ".join(f"v{d['version']} @ {d['path']}" for d in stale)
    active_desc = f"active v{active_ver}" + (f" @ {active['path']}" if active else "")
    remediation = (
        "Remove stale copies (active install is fine): "
        + " ; ".join(f"rm -f {d['path']}" for d in stale)
        + "  then re-run `perseus doctor`"
    )
    return DoctorResult(
        "duplicate_installs", "warn", "Duplicate installs",
        f"{len(installs)} copies found — {active_desc}; stale: {stale_desc}",
        remediation,
    )


def _abbrev_home(path_str: str) -> str:
    """Return ``path_str`` with the user's home directory collapsed to ``~``.

    Freshness warnings must name the *exact* file so an operator does not audit
    the wrong one when several outputs share a basename like ``AGENTS.md``
    (#798). An absolute path is unambiguous; home-abbreviation keeps it
    readable."""
    try:
        return str(Path("~") / Path(path_str).relative_to(Path.home()))
    except (ValueError, OSError):
        return path_str


_BUILD_SHA_VALUE_RE = re.compile(r"^([0-9a-f]{4,40})(-dirty)?$", re.IGNORECASE)


def _parse_build_provenance(value: object) -> dict:
    """Parse a build SHA literal without treating arbitrary text as metadata.

    Build metadata predates this check in some installed artifacts, so missing,
    empty, and legacy values are represented as an explicit unknown state. Only
    a hexadecimal short/full SHA with an optional ``-dirty`` suffix is exposed
    to doctor output.
    """
    if not isinstance(value, str):
        return {"sha": None, "dirty": None, "state": "unknown"}
    text = value.strip().lower()
    if text in {"", "?", "unknown", "legacy", "none"}:
        return {"sha": None, "dirty": None, "state": "unknown"}
    match = _BUILD_SHA_VALUE_RE.fullmatch(text)
    if not match:
        return {"sha": None, "dirty": None, "state": "unknown"}
    dirty = bool(match.group(2))
    return {"sha": match.group(1), "dirty": dirty, "state": "dirty" if dirty else "clean"}


def _read_perseus_module_build_sha(path: str) -> str:
    """Read a build SHA literal from an artifact without importing it.

    Importing a discovered ``perseus.py`` copy could execute stale code and
    shadow the active module. The build assignment is near the artifact head,
    so bounded text parsing is sufficient and keeps this check side-effect free.
    """
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            head = f.read(16384)
    except Exception:
        return ""
    match = re.search(
        r"^\s*_PERSEUS_BUILD_SHA\s*=\s*(['\"])(.*?)\1\s*(?:#.*)?$",
        head,
        re.MULTILINE,
    )
    return match.group(2).strip() if match else ""


def _read_perseus_module_provenance(path: str) -> dict:
    """Return sanitized build provenance parsed from an artifact file."""
    return _parse_build_provenance(_read_perseus_module_build_sha(path))


def _doctor_safe_path(path: Path | None) -> str | None:
    """Return a printable, home-abbreviated path for structured output."""
    if path is None:
        return None
    text = str(path)
    return "".join(char if char.isprintable() and char not in "\r\n\t" else "?" for char in text)


def _doctor_source_root(cfg: dict, workspace: Path, artifact_path: Path) -> tuple[Path | None, bool]:
    """Resolve an explicit or narrowly discoverable source checkout.

    Explicit ``doctor.source_root`` is authoritative. Without it, only the
    canonical checkout layout at the requested workspace or beside the active
    root-level artifact is considered; no ancestor or filesystem scan is done.
    The boolean says whether the root was explicitly configured.
    """
    doctor_cfg = cfg.get("doctor", {}) if isinstance(cfg, dict) else {}
    configured = doctor_cfg.get("source_root") if isinstance(doctor_cfg, dict) else None
    if configured is not None and str(configured).strip():
        try:
            root = Path(configured).expanduser()
            if not root.is_absolute():
                root = workspace / root
            return root.resolve(), True
        except Exception:
            return None, True

    candidates: list[Path] = [workspace]
    if artifact_path.name == "perseus.py":
        candidates.append(artifact_path.parent)
    elif artifact_path.name in {"doctor.py", "__init__.py"} and artifact_path.parent.name == "perseus":
        candidates.append(artifact_path.parent.parent.parent)

    seen: set[str] = set()
    for candidate in candidates:
        try:
            root = candidate.resolve()
            key = str(root)
        except Exception:
            continue
        if key in seen:
            continue
        seen.add(key)
        if (
            (root / ".git").exists()
            and (root / "src" / "perseus").is_dir()
            and (
                (root / "VERSION").is_file()
                or (root / "scripts" / "build.py").is_file()
            )
        ):
            return root, False
    return None, False


def _doctor_read_source_provenance(
    source_root: Path | None,
    *,
    require_markers: bool = False,
) -> dict:
    """Read current checkout SHA and cleanliness with fail-closed states."""
    source = {"root": _doctor_safe_path(source_root), "sha": None, "dirty": None, "state": "unavailable"}
    if source_root is None:
        return source
    if require_markers and not (
        (source_root / ".git").exists()
        and (source_root / "src" / "perseus").is_dir()
        and (
            (source_root / "VERSION").is_file()
            or (source_root / "scripts" / "build.py").is_file()
        )
    ):
        return source
    try:
        sha_result = subprocess.run(
            ["git", "-C", str(source_root), "rev-parse", "--short", "HEAD"],
            capture_output=True, text=True, timeout=5,
        )
        sha = sha_result.stdout.strip().lower() if sha_result.returncode == 0 else ""
        if not re.fullmatch(r"[0-9a-f]{4,40}", sha):
            sha = ""

        status_result = subprocess.run(
            ["git", "-C", str(source_root), "status", "--porcelain", "--untracked-files=all"],
            capture_output=True, text=True, timeout=5,
        )
        if status_result.returncode == 0:
            dirty = bool(status_result.stdout.strip())
            source.update({"sha": sha or None, "dirty": dirty, "state": "dirty" if dirty else "clean"})
        else:
            source.update({"sha": sha or None, "state": "unknown"})
    except Exception:
        # Doctor must remain useful when git is absent or a checkout is gone.
        pass
    return source


def _doctor_check_provenance_drift(cfg: dict, workspace: Path) -> DoctorResult:
    """Compare installed artifact provenance with a known current checkout."""
    try:
        artifact_path = Path(__file__).resolve()
    except Exception:
        artifact_path = Path(__file__)
    artifact = _read_perseus_module_provenance(str(artifact_path))
    artifact["path"] = _doctor_safe_path(artifact_path)

    # A source-package import keeps the build assignment in __init__.py; the
    # generated single-file artifact keeps it in perseus.py itself.
    if artifact["state"] == "unknown" and artifact_path.name == "doctor.py" and artifact_path.parent.name == "perseus":
        package_init = artifact_path.parent / "__init__.py"
        artifact = _read_perseus_module_provenance(str(package_init))
        artifact["path"] = _doctor_safe_path(package_init)

    source_root, explicitly_configured = _doctor_source_root(cfg, workspace, artifact_path)
    source = _doctor_read_source_provenance(
        source_root,
        require_markers=not explicitly_configured,
    )

    reasons: list[str] = []
    if artifact["dirty"] is True and source["dirty"] is False:
        reasons.append("artifact_dirty_source_clean")
    if artifact["sha"] and source["sha"] and artifact["sha"] != source["sha"]:
        reasons.append("sha_mismatch")

    if reasons:
        comparison = reasons[0]
        status = "warn"
        remediation = (
            "Reinstall Perseus from the current source checkout to refresh the "
            "installed artifact provenance."
        )
    elif source["state"] == "unavailable":
        comparison = "artifact_only" if artifact["state"] != "unknown" else "unknown"
        status = "ok"
        remediation = ""
    elif artifact["state"] == "unknown":
        comparison = "unknown"
        status = "ok"
        remediation = ""
    elif artifact["sha"] and source["sha"] and artifact["sha"] == source["sha"]:
        comparison = "match" if artifact["dirty"] == source["dirty"] else "state_mismatch"
        status = "ok"
        remediation = ""
    else:
        comparison = "unknown"
        status = "ok"
        remediation = ""

    artifact_state = artifact["state"]
    artifact_sha = artifact["sha"] or "unknown"
    artifact_suffix = "-dirty" if artifact["dirty"] is True else ""
    source_sha = source["sha"] or "unknown"
    source_state = source["state"]
    value = (
        f"artifact g{artifact_sha}{artifact_suffix} ({artifact_state}); "
        f"source g{source_sha} ({source_state}); comparison={comparison}"
    )
    details = {
        "artifact": artifact,
        "source": source,
        "comparison": comparison,
        "reasons": reasons,
        "source_root_configured": explicitly_configured,
    }
    return DoctorResult("provenance_drift", status, "Build provenance", value, remediation, details)


def _doctor_check_render_freshness(cfg: dict, workspace: Path) -> DoctorResult:
    """Warn when a rendered output is older than render.staleness_warn_hours (#431).

    A scheduled render job that silently stops — e.g. a launchd plist calling a
    stale binary that exits 0 (#430) — leaves the rendered AGENTS.md/CLAUDE.md
    frozen with no error and no log warning. This check reads each known
    rendered output's freshness, preferring the embedded Perseus generation
    header (deterministic) and falling back to file mtime, and flags staleness
    so it is visible without manually stat-ing files."""
    threshold_h = cfg.get("render", {}).get("staleness_warn_hours", 48)
    try:
        threshold_h = float(threshold_h)
    except (TypeError, ValueError):
        threshold_h = 48.0
    if threshold_h <= 0:
        return DoctorResult("render_freshness", "ok", "rendered output freshness",
                            "disabled (render.staleness_warn_hours=0)", "")

    # Candidate rendered outputs: assistant-format defaults + configured watch list.
    candidates: list[Path] = []
    try:
        for ft in FORMAT_TARGETS.values():
            candidates.append(workspace / ft.default_output)
    except Exception:
        candidates += [workspace / n for n in ("AGENTS.md", "CLAUDE.md", ".cursorrules")]
    for extra in cfg.get("render", {}).get("staleness_watch", []) or []:
        p = Path(extra).expanduser()
        candidates.append(p if p.is_absolute() else workspace / p)

    header_re = re.compile(r"generated by \[Perseus\].*?on (\d{4}-\d{2}-\d{2} \d{2}:\d{2}) UTC")
    now_utc = datetime.now(timezone.utc)

    found: list[tuple[str, float]] = []
    seen: set[str] = set()
    for p in candidates:
        rp = str(p)
        if rp in seen:
            continue
        seen.add(rp)
        if not p.is_file():
            continue
        gen_dt = None
        try:
            m = header_re.search(p.read_text(errors="replace")[:1000])
            if m:
                gen_dt = datetime.strptime(m.group(1), "%Y-%m-%d %H:%M").replace(tzinfo=timezone.utc)
        except Exception:
            pass
        if gen_dt is None:
            try:
                gen_dt = datetime.fromtimestamp(p.stat().st_mtime, tz=timezone.utc)
            except OSError:
                continue
        age_h = (now_utc - gen_dt).total_seconds() / 3600.0
        # #798: keep the absolute path — the warning names the exact file so a
        # workspace AGENTS.md is never confused with a startup target rendered
        # elsewhere. Display is home-abbreviated at format time.
        found.append((str(p), age_h))

    if not found:
        return DoctorResult("render_freshness", "ok", "rendered output freshness",
                            "no rendered outputs found", "")

    def _fmt_age(h: float) -> str:
        return f"{h / 24:.1f}d" if h >= 48 else f"{h:.1f}h"

    found.sort(key=lambda t: t[1], reverse=True)
    oldest_path, oldest_age = found[0]
    summary = ", ".join(f"{_abbrev_home(pth)} {_fmt_age(a)}" for pth, a in found[:4])
    if oldest_age > threshold_h:
        return DoctorResult(
            "render_freshness", "warn", "rendered output freshness",
            f"{summary} (threshold {threshold_h:.0f}h)",
            # #798: name the EXACT stale file (not a bare basename) so a
            # multi-AGENTS setup doesn't send the operator to audit the wrong
            # one, and point at the two things that actually resolve it —
            # watching the real target and the authoritative startup-route check.
            f"`{_abbrev_home(oldest_path)}` looks stale — re-run `perseus render` "
            "or check the scheduled render job (launchctl/systemctl/crontab). If "
            "your startup-memory target renders to a different path (e.g. outside "
            "this workspace), add it to render.staleness_watch so this check "
            "watches the right file; the 'AGENTS.md startup-memory route' check "
            "audits the startup target directly.")
    return DoctorResult("render_freshness", "ok", "rendered output freshness", summary, "")


def _doctor_check_agents_startup_route(cfg: dict, workspace: Path) -> DoctorResult:
    """Validate the AGENTS.md startup-memory route end-to-end (#793).

    Clients that load an instructions file at startup instead of running a
    session-start hook — Rovo Dev CLI is the motivating case (perseus#790, whose
    event hooks can't inject context) — get their startup memory by *rendering
    it into AGENTS.md before the session*, not from a hook. When that render
    silently stops or was never wired, AGENTS.md freezes with no startup-memory
    block and no error, and recall "does nothing" for reasons that take manual
    forensics to find. This check confirms, in one place, that:

      1. an ``AGENTS.md`` exists in the workspace (else the route isn't in use),
      2. it contains a Perseus startup-memory block — the ``on_demand`` retrieval
         pointer or an active-recall Persistent Memory section, and
      3. it is not older than its render source (``.perseus/context.md`` /
         ``.hermes.md``),

    reporting the first break so the user knows *where* the path is broken
    rather than having to hand-inspect the source, the rendered file, the hook,
    and the connector separately.
    """
    check_id = "agents_startup_route"
    label = "AGENTS.md startup-memory route"

    # Resolve the AGENTS.md target exactly like `perseus render --format agents-md`.
    try:
        agents_path = Path(get_default_output_path("agents-md", str(workspace)))
    except Exception:
        agents_path = workspace / "AGENTS.md"

    if not agents_path.is_file():
        # No AGENTS.md → this workspace doesn't use the AGENTS route. Not a fault
        # (hook-based clients never render one); report informational, not warn.
        return DoctorResult(check_id, "ok", label,
                            "not in use (no AGENTS.md in workspace)", "")

    try:
        text = agents_path.read_text(errors="replace")
    except OSError as exc:
        return DoctorResult(check_id, "error", label,
                            f"AGENTS.md present but unreadable: {exc}",
                            f"Check permissions on {agents_path}")

    try:
        rel = str(agents_path.relative_to(workspace))
    except ValueError:
        rel = agents_path.name

    # Which startup-memory block, if any, did the last render inject?
    has_pointer = _MEMORY_POINTER_HEADER in text
    has_active = PERSISTENT_MEMORY_HEADER in text
    if not (has_pointer or has_active):
        return DoctorResult(
            check_id, "warn", label,
            f"{rel} has no startup-memory block",
            "Re-render it with `perseus render <source> --format agents-md` "
            "(memory injection appends the block). If the block still doesn't "
            f"appear, check the memory posture/connector via the {MEMORY_BRAND} "
            "row above.")
    block = "on_demand pointer" if has_pointer else "active-recall (Persistent Memory)"

    # Freshness vs the render source — a frozen AGENTS.md is the #790/#430 failure
    # mode (a scheduled render that silently stopped leaves stale startup memory).
    source = None
    for name in (".perseus/context.md", ".hermes.md"):
        p = workspace / name
        if p.is_file():
            source = p
            break
    if source is not None:
        try:
            # +1s tolerance so a render that touches both files in one run,
            # or equal mtimes, doesn't flap as "stale".
            if source.stat().st_mtime > agents_path.stat().st_mtime + 1.0:
                return DoctorResult(
                    check_id, "warn", label,
                    f"{rel} ({block}) is older than its source {source.name}",
                    "Re-render AGENTS.md — its source context has changed since "
                    "the last render (`perseus render <source> --format agents-md`), "
                    "or check the scheduled render job (launchctl/systemctl/crontab).")
        except OSError:
            pass

    src_note = f", source {source.name}" if source is not None else ""
    return DoctorResult(check_id, "ok", label,
                        f"{rel}: {block} block present{src_note}", "")


def _doctor_check_vault_config(cfg: dict, workspace: Path) -> DoctorResult:
    """Report the canonical Perseus Vault configuration state."""
    resolved = _resolve_vault_config(cfg)
    if resolved:
        return DoctorResult(
            "vault_config", "ok", "memory config key",
            "canonical (`perseus_vault:`)", "",
        )
    return DoctorResult(
        "vault_config", "ok", "memory config key",
        "canonical defaults", "",
    )


