def _effective_profile_summary(cfg: dict) -> dict:
    """Build the structured trust summary used by `perseus trust` (task-45).

    Returns a dict suitable for both human rendering and `--json` output.
    Reflects the *effective* config after profile + user overrides have been
    merged — so the human report shows what's actually in force, not the
    profile's nominal defaults.
    """
    perms_cfg = cfg.get("permissions", {}) or {}
    render_cfg = cfg.get("render", {}) or {}
    gen_cfg = cfg.get("generation", {}) or {}
    serve_cfg = cfg.get("serve", {}) or {}
    red_cfg = cfg.get("redaction", {}) or {}

    configured = perms_cfg.get("profile")
    canonical = None
    if configured:
        name = str(configured).strip().lower()
        if name in PERMISSION_PROFILES:
            canonical = name
    serve_summary = _serve_trust_summary(cfg)

    return {
        "version": _PERSEUS_VERSION,
        "serve": serve_summary,
        "permissions": {
            "configured_profile": configured,
            "applied_profile": canonical,
            "available_profiles": sorted(PERMISSION_PROFILES.keys()),
        },
        "effective": {
            "render": {
                "allow_query_shell": bool(render_cfg.get("allow_query_shell", False)),
                "allow_agent_shell": bool(render_cfg.get("allow_agent_shell", False)),
                "allow_services_command": bool(render_cfg.get("allow_services_command", False)),
                "allow_outside_workspace": bool(render_cfg.get("allow_outside_workspace", False)),
            },
            "generation": {
                "enabled": bool(gen_cfg.get("enabled", False)),
            },
            "serve": {
                "bind": serve_summary["bind_host"],
                "bind_host": serve_summary["bind_host"],
                "auth_token_set": serve_summary["auth_token_set"],
                "loopback_only": serve_summary["loopback_only"],
                "allow_insecure_remote": serve_summary["allow_insecure_remote"],
            },
            "redaction": {
                "enabled": bool(red_cfg.get("enabled", True)),
                "include_defaults": bool(red_cfg.get("include_defaults", True)),
                "custom_patterns": len(list(red_cfg.get("patterns") or [])),
                "rules_active": len(_compile_redaction_rules(cfg)),
            },
        },
    }


def cmd_trust(args, cfg) -> int:
    """`perseus trust` — show effective permissions and audit posture (task-45, task-47)."""
    sub = getattr(args, "trust_command", None) or "profile"
    summary = _effective_profile_summary(cfg)
    audit_summary = _audit_summary(cfg)
    summary["audit"] = audit_summary

    if sub == "audit":
        entries = _read_audit_entries(cfg, limit=int(getattr(args, "tail", 10) or 10))
        if getattr(args, "json", False):
            print(json.dumps({
                "summary": audit_summary,
                "entries": entries,
            }, indent=2, sort_keys=True))
            return 0
        print(f"perseus trust audit — Perseus v{_PERSEUS_VERSION}")
        print(f"  enabled:           {audit_summary.get('enabled')}")
        print(f"  log_path:          {audit_summary.get('log_path')}")
        print(f"  total_events:      {audit_summary.get('total_events', 0)}")
        last = audit_summary.get("last_event_ts")
        print(f"  last_event_ts:     {last or '(none)'}")
        counts = audit_summary.get("counts_by_type", {}) or {}
        if counts:
            print("  counts_by_type:")
            for k in sorted(counts):
                print(f"    {k}: {counts[k]}")
        print("")
        if not entries:
            print("(no audit entries)")
            return 0
        print(f"Recent entries (most recent last, up to {len(entries)}):")
        for e in entries:
            ts = e.get("ts", "?")
            et = e.get("event_type", "?")
            extras = {k: v for k, v in e.items()
                      if k not in {"ts", "event_type", "perseus_version", "pid"}}
            extras_s = " ".join(f"{k}={v!r}" for k, v in sorted(extras.items()))
            print(f"  {ts}  {et}  {extras_s}")
        return 0

    if getattr(args, "json", False):
        print(json.dumps(summary, indent=2, sort_keys=True))
        return 0

    if sub in ("profile", None):
        perms = summary["permissions"]
        eff = summary["effective"]
        print(f"perseus trust — Perseus v{_PERSEUS_VERSION}")
        configured = perms["configured_profile"]
        applied = perms["applied_profile"]
        if configured is None:
            print("  profile:           (none — using DEFAULT_CONFIG values)")
        elif applied is None:
            print(f"  profile:           {configured!r} ⚠ unknown — ignored. "
                  f"Available: {', '.join(perms['available_profiles'])}")
        elif applied != str(configured).strip().lower():
            print(f"  profile:           {applied} (configured as {configured!r})")
        else:
            print(f"  profile:           {applied}")
        print(f"  available:         {', '.join(perms['available_profiles'])}")
        print("")
        print("Effective permissions (profile + explicit overrides):")
        print(f"  render.allow_query_shell:       {eff['render']['allow_query_shell']}")
        print(f"  render.allow_agent_shell:       {eff['render']['allow_agent_shell']}")
        print(f"  render.allow_services_command:  {eff['render']['allow_services_command']}")
        print(f"  render.allow_outside_workspace: {eff['render']['allow_outside_workspace']}")
        print(f"  generation.enabled:             {eff['generation']['enabled']}")
        print(f"  serve.bind_host:                {eff['serve']['bind_host']}")
        print(f"  serve.auth_token_set:           {eff['serve']['auth_token_set']}")
        print(f"  serve.loopback_only:            {eff['serve']['loopback_only']}")
        print(f"  serve.allow_insecure_remote:    {eff['serve']['allow_insecure_remote']}")
        red = eff.get("redaction", {})
        print(
            f"  redaction.enabled:              {red.get('enabled', True)} "
            f"(rules active: {red.get('rules_active', 0)}, "
            f"custom: {red.get('custom_patterns', 0)})"
        )
        print("")
        print("Audit log (task-47):")
        print(f"  audit.enabled:                  {audit_summary.get('enabled')}")
        print(f"  audit.log_path:                 {audit_summary.get('log_path')}")
        print(f"  audit.total_events:             {audit_summary.get('total_events', 0)}")
        last = audit_summary.get("last_event_ts")
        if last:
            print(f"  audit.last_event_ts:            {last}")
        return 0

    sys.stderr.write(f"perseus trust: unknown subcommand {sub!r}\n")
    return 2


def run_doctor_checks(cfg: dict, workspace: Path) -> dict:
    """Run the full doctor check suite and return the structured result.

    This is the machine-readable core of `perseus doctor --json`, extracted
    so other surfaces (notably the MCP `perseus_get_health` tool in
    ``mode="doctor"``) can return the identical payload instead of scraping
    prose (#852). Returns a dict: perseus_version, workspace, checks,
    summary, exit.
    """
    cfg = dict(cfg)
    cfg["render"] = dict(cfg.get("render", {}))
    if cfg["render"].get("cache_dir") == DEFAULT_CONFIG.get("render", {}).get("cache_dir"):
        cfg["render"]["cache_dir"] = str(PERSEUS_HOME / "cache")

    # Checks are independent and mostly I/O-bound (HTTP / subprocess / file
    # probes), so run them in a thread pool instead of serially. User-facing
    # latency was the SUM of every check's latency, dominated by the slow
    # network/subprocess ones (llm_reachable's 5s HTTP timeout, llm_functional's
    # round-trip, vault_bridge's subprocess + MCP handshake). ThreadPoolExecutor
    # .map preserves _DOCTOR_CHECKS order; each check stays exception-isolated so
    # one failure can't abort the run. (#449)
    def _run_doctor_check(check_fn) -> DoctorResult:
        try:
            return check_fn(cfg, workspace)
        except Exception as exc:
            return DoctorResult(
                check_fn.__name__.replace("_doctor_check_", ""),
                "error", check_fn.__name__, str(exc), ""
            )

    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=min(len(_DOCTOR_CHECKS), 8)) as executor:
        results: list[DoctorResult] = list(executor.map(_run_doctor_check, _DOCTOR_CHECKS))

    ok = sum(1 for r in results if r.status == "ok")
    warn = sum(1 for r in results if r.status == "warn")
    err = sum(1 for r in results if r.status == "error")
    exit_code = 1 if err > 0 else 0

    return {
        "perseus_version": _PERSEUS_VERSION,
        "workspace": str(workspace),
        "checks": [
            {
                "id": r.id,
                "status": r.status,
                "label": r.label,
                "value": r.value,
                **({"remediation": r.remediation} if r.remediation else {}),
                **({"details": r.details} if r.details is not None else {}),
            }
            for r in results
        ],
        "summary": {"ok": ok, "warn": warn, "error": err},
        "exit": exit_code,
    }


def cmd_doctor(args, cfg) -> int:
    """Run readiness checks and report status."""
    workspace = Path(getattr(args, "workspace", None) or os.getcwd()).resolve()
    use_json = getattr(args, "json", False)
    try:
        cfg = load_config(workspace)
    except Exception:
        # Keep going so doctor can report config/parser failures as checks.
        pass

    output = run_doctor_checks(cfg, workspace)
    ok = output["summary"]["ok"]
    warn = output["summary"]["warn"]
    err = output["summary"]["error"]
    exit_code = output["exit"]

    if use_json:
        import json as _json
        print(_json.dumps(output, indent=2))
    else:
        status_icons = {"ok": "✓", "warn": "⚠", "error": "✗"}
        print(f"perseus doctor — workspace: {workspace}")
        for c in output["checks"]:
            icon = status_icons.get(c["status"], "?")
            print(f"{icon} {c['label']:<40s} {c['value']}")
        print(f"─ Summary: {ok} ok · {warn} warning · {err} errors  (exit {exit_code})")

    return exit_code
# ─────────────────────────────── Scheduler ────────────────────────────────────
# Cross-platform scheduling commands: launchd (macOS), cron (POSIX), systemd (Linux)

LAUNCHD_TEMPLATE = """\
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
  <dict>
    <key>Label</key>
    <string>{label}</string>
    <key>ProgramArguments</key>
    <array>
{program_arguments}
    </array>
    <key>WorkingDirectory</key>
    <string>{workdir}</string>
    <key>StartInterval</key>
    <integer>{interval}</integer>
    <key>RunAtLoad</key>
    <true/>
    <key>StandardOutPath</key>
    <string>{stdout_log}</string>
    <key>StandardErrorPath</key>
    <string>{stderr_log}</string>
  </dict>
</plist>
"""


def _perseus_launcher() -> tuple[list[str], bool]:
    """Resolve a version-stable way to invoke ``perseus`` from a scheduled job.

    Scheduled jobs (launchd/cron/systemd) persist for months across Perseus
    upgrades. Baking in the versioned interpreter path (``sys.executable``) or
    the versioned site-packages script (``__file__``) means a Python
    minor-version bump (e.g. 3.13 → 3.14) silently strands the job on the old
    binary — pip installs the new console script under a new path while the
    plist keeps calling the old one, with ``LastExitStatus = 0`` and no error
    (#430).

    Prefer a stable console-script launcher that always resolves to the current
    install, in order:

      1. ``~/.local/bin/perseus`` — the stable user symlink that survives
         Python minor-version bumps (recommended in the install docs).
      2. ``perseus`` on ``PATH`` — the pip console script.
      3. ``{sys.executable} {__file__}`` — last-resort, version-specific
         fallback (matches legacy behaviour).

    Returns ``(argv_tokens, is_stable)`` where ``is_stable`` is ``False`` only
    for the version-specific fallback so callers can warn.
    """
    import shutil as _shutil

    local_bin = Path.home() / ".local" / "bin" / "perseus"
    try:
        if local_bin.exists():
            return [str(local_bin)], True
    except OSError:
        pass

    # shutil.which can raise on some platforms (e.g. its win32 branch touches
    # _winapi, which is absent off-Windows) — degrade to the fallback instead
    # of crashing the scheduler command.
    try:
        which = _shutil.which("perseus")
    except Exception:
        which = None
    if which:
        return [which], True

    # Fallback: version-specific interpreter + script (may go stale on upgrade).
    return [str(Path(sys.executable).resolve()), str(Path(__file__).resolve())], False


def _resolve_job(args, cfg):
    """#693: resolve the scheduled job into (cli_tokens, tag, label_stem).

    ``render`` (the default, and the only job before #693) needs a source and
    an output path; ``maintain`` is the hands-off memory hygiene pass
    (``perseus vault maintain``) and takes neither. The tag is the marker the
    installers use for dedup/uninstall (``# perseus-render`` stays byte-
    identical so existing installed entries keep matching).
    """
    job = getattr(args, "job", "render") or "render"
    if job == "maintain":
        tokens = ["vault", "maintain"]
        hygiene = (cfg or {}).get("hygiene", {}) if isinstance(cfg, dict) else {}
        # A report-only rollout (hygiene.dry_run: true) bakes --dry-run into
        # the scheduled entry; flip the config and reinstall to go live.
        if hygiene.get("dry_run"):
            tokens.append("--dry-run")
        return tokens, "perseus-hygiene", "hygiene"
    if job != "render":
        print(f"Error: unknown --job {job!r} (expected: render, maintain)", file=sys.stderr)
        sys.exit(1)
    if not getattr(args, "source", None) or not getattr(args, "output", None):
        print("Error: --job render requires a source file and --output.", file=sys.stderr)
        sys.exit(1)
    source_path = Path(args.source).expanduser().resolve()
    output_path = Path(args.output).expanduser().resolve()
    tokens = ["render", str(source_path), "--output", str(output_path)]
    return tokens, "perseus-render", source_path.stem


def _hygiene_schedule_minutes(cfg) -> int:
    """#693: scheduled-maintain cadence from the hygiene config (default nightly)."""
    hygiene = (cfg or {}).get("hygiene", {}) if isinstance(cfg, dict) else {}
    try:
        minutes = int(hygiene.get("schedule_minutes", 1440))
    except (TypeError, ValueError):
        minutes = 1440
    return minutes if minutes > 0 else 1440


def cmd_launchd(args, cfg):
    if sys.platform != "darwin":
        print("Error: `perseus launchd` is only supported on macOS.", file=sys.stderr)
        sys.exit(1)

    job_tokens, _tag, label_stem = _resolve_job(args, cfg)
    is_render = job_tokens[0] == "render"
    if is_render:
        source_path = Path(args.source).expanduser().resolve()
        if not source_path.exists():
            print(f"Error: file not found: {source_path}", file=sys.stderr)
            sys.exit(1)
        output_path = Path(args.output).expanduser().resolve()
        output_path.parent.mkdir(parents=True, exist_ok=True)
        workdir = _infer_workspace(source_path)
        default_label = f"com.perseus.render.{source_path.stem}"
        interval = int(args.interval)
    else:
        # maintain: no source/output; run from HOME; default cadence comes
        # from hygiene.schedule_minutes unless --interval was given explicitly.
        workdir = Path.home()
        default_label = "com.perseus.hygiene"
        interval = int(args.interval) if args.interval != 300 else _hygiene_schedule_minutes(cfg) * 60

    launch_agents = Path.home() / "Library" / "LaunchAgents"
    launch_agents.mkdir(parents=True, exist_ok=True)

    logs_dir = PERSEUS_HOME / "logs"
    logs_dir.mkdir(parents=True, exist_ok=True)

    label = args.label or default_label
    plist_path = launch_agents / f"{label}.plist"
    launcher, stable = _perseus_launcher()
    stdout_log = logs_dir / f"{label}.out.log"
    stderr_log = logs_dir / f"{label}.err.log"

    # Build the ProgramArguments <string> list from a version-stable launcher
    # so a Python minor-version upgrade does not strand the job (#430).
    prog_tokens = launcher + job_tokens
    program_arguments = "\n".join(f"      <string>{tok}</string>" for tok in prog_tokens)

    content = LAUNCHD_TEMPLATE.format(
        label=label,
        program_arguments=program_arguments,
        workdir=str(workdir),
        interval=interval,
        stdout_log=str(stdout_log),
        stderr_log=str(stderr_log),
    )

    if plist_path.exists() and not args.force:
        print(f"Error: {plist_path} already exists. Use --force to overwrite.", file=sys.stderr)
        sys.exit(1)

    plist_path.write_text(content, encoding="utf-8")

    print(f"✔ Wrote LaunchAgent plist: {plist_path}")
    print(f"  Launcher: {' '.join(launcher)}")
    if not stable:
        print("  ⚠ Could not find a stable `perseus` launcher (~/.local/bin/perseus or on PATH);")
        print("    falling back to a version-specific path that may go stale after a Python upgrade.")
        print("    Install the console script (`pipx install perseus-ctx` or ensure ~/.local/bin is on PATH).")
    print()
    print("Next steps:")
    print(f"  1. Load it:    launchctl load {plist_path}")
    print(f"  2. Start now:  launchctl start {label}")
    print(f"  3. Check logs: tail -f {stdout_log} {stderr_log}")


# ─────────────────────────────── cron (POSIX) ────────────────────────────────

def cmd_cron(args, cfg):
    """Generate a crontab entry for a scheduled Perseus job.

    POSIX-oriented: works on systems with crontab (macOS, Linux, BSD).
    Recommended over launchd/systemd when portability matters.
    #693: ``--job render`` (default; byte-identical to the pre-#693 entry)
    or ``--job maintain`` (hands-off memory hygiene).
    """
    job_tokens, tag, _stem = _resolve_job(args, cfg)
    is_maintain = tag == "perseus-hygiene"

    raw_every = getattr(args, "every", None)
    if raw_every is None:
        # Defaults are job-aware: renders poll (5 min), hygiene runs on the
        # configured cadence (hygiene.schedule_minutes, nightly).
        raw_every = _hygiene_schedule_minutes(cfg) if is_maintain else 5
    try:
        every = int(raw_every)
    except (TypeError, ValueError):
        print(f"Error: --every must be an integer (got {raw_every!r})", file=sys.stderr)
        sys.exit(1)
    if every <= 0:
        print("Error: --every must be > 0", file=sys.stderr)
        sys.exit(1)

    launcher, stable = _perseus_launcher()

    # Build crontab schedule expression
    if every == 1:
        schedule = "* * * * *"
    elif every < 60:
        schedule = f"*/{every} * * * *"
    elif every == 60:
        schedule = "0 * * * *"
    else:
        hours = every // 60
        schedule = f"0 */{hours} * * *"

    cmd = " ".join(launcher + job_tokens)
    # Suppress crontab MAILTO noise; route stderr to /dev/null on success
    entries = [f"{schedule} {cmd} >/dev/null 2>&1  # {tag}"]
    if is_maintain:
        # Companion weekly VACUUM (hygiene.vacuum_every_runs at the nightly
        # default ≈ weekly). cron is stateless, so an explicit weekly entry
        # replaces an every-Nth-run counter. Skipped when the throttle is 0.
        hygiene = (cfg or {}).get("hygiene", {}) if isinstance(cfg, dict) else {}
        try:
            vacuum_runs = int(hygiene.get("vacuum_every_runs", 7) or 0)
        except (TypeError, ValueError):
            vacuum_runs = 7
        if vacuum_runs > 0:
            entries.append(f"0 3 * * 0 {cmd} --vacuum >/dev/null 2>&1  # {tag}-vacuum")

    if not stable:
        print("# ⚠ Could not find a stable `perseus` launcher (~/.local/bin/perseus or on PATH);")
        print("#   the entry below uses a version-specific path that may go stale after a Python upgrade.")

    if args.install:
        if sys.platform == "win32":
            # #694: no crontab on native Windows — route to the Task
            # Scheduler backend so `cron create --install` still lands a
            # working schedule instead of a "crontab not found" error.
            print("> crontab is not available on native Windows — installing a Windows Scheduled Task instead.")
            return cmd_schtasks(args, cfg)
        try:
            existing = subprocess.run(
                ["crontab", "-l"],
                capture_output=True, text=True, check=False,
            )
            current = existing.stdout if existing.returncode == 0 else ""
        except FileNotFoundError:
            print("Error: `crontab` not found in PATH. Install cron first.", file=sys.stderr)
            sys.exit(1)

        # #693: dedup per-tag so a render entry and a hygiene entry coexist.
        if f"# {tag}" in current:
            print(f"> ⚠ A {tag} entry already exists in crontab. Remove it first or edit by hand.")
            print(current)
            sys.exit(1)

        new_crontab = current.rstrip() + ("\n" if current.strip() else "") + "\n".join(entries) + "\n"
        try:
            proc = subprocess.run(["crontab", "-"], input=new_crontab, text=True,
                                  capture_output=True, check=False)
            if proc.returncode != 0:
                print(f"Error: `crontab -` failed: {proc.stderr.strip()}", file=sys.stderr)
                sys.exit(1)
        except FileNotFoundError:
            print("Error: `crontab` not found in PATH.", file=sys.stderr)
            sys.exit(1)
        print("✔ Installed crontab entr" + ("ies:" if len(entries) > 1 else "y:"))
        for entry in entries:
            print(f"  {entry}")
        print()
        print("Verify with: crontab -l")
        print(f"Remove with: crontab -e  (delete the line(s) tagged `# {tag}`)")
        return

    # Default: print the entries
    print("# Add this to your crontab (run `crontab -e`):")
    for entry in entries:
        print(entry)
    print()
    print("Or install automatically with: perseus cron ... --install")


# ─────────────────────────────── systemd (Linux) ─────────────────────────────

SYSTEMD_SERVICE_TEMPLATE = """\
[Unit]
Description={description}
After=default.target

[Service]
Type=oneshot
ExecStart={exec_start}
"""

SYSTEMD_TIMER_TEMPLATE = """\
[Unit]
Description={description}

[Timer]
OnBootSec=1min
OnUnitActiveSec={interval}
Unit={unit}.service

[Install]
WantedBy=timers.target
"""


def _parse_systemd_interval(raw: str) -> str:
    """Accept '5m', '2h', or systemd-native like '30s'/'1h30min' — return systemd time spec.

    Defaults to '5min' if empty. Raises ValueError on garbage.
    """
    s = (raw or "").strip().lower()
    if not s:
        return "5min"
    m = re.fullmatch(r"(\d+)\s*([smh])", s)
    if m:
        n, unit = m.group(1), m.group(2)
        return {"s": f"{n}s", "m": f"{n}min", "h": f"{n}h"}[unit]
    # passthrough for already-systemd-native values
    if re.fullmatch(r"[\d\s a-z]+", s):
        return s
    raise ValueError(f"unrecognised interval: {raw!r}")


def cmd_systemd(args, cfg):
    """Scaffold ~/.config/systemd/user/<unit>.{service,timer} units.

    #693: ``--job render`` (default) writes perseus-render.{service,timer}
    exactly as before; ``--job maintain`` writes perseus-hygiene.* running
    ``perseus vault maintain`` on the hygiene cadence.
    """
    if sys.platform == "darwin":
        print("Use `perseus launchd` on macOS.", file=sys.stderr)
        sys.exit(1)
    if sys.platform != "linux":
        suffix = " Systemd support is deferred; use Windows Task Scheduler via `perseus schtasks create`." if sys.platform == "win32" else ""
        print(f"Error: `perseus systemd` is only supported on Linux.{suffix}", file=sys.stderr)
        sys.exit(1)

    job_tokens, tag, stem = _resolve_job(args, cfg)
    is_maintain = tag == "perseus-hygiene"
    unit = "perseus-hygiene" if is_maintain else f"perseus-render-{stem}"
    service_desc = (
        "Perseus memory hygiene (vault maintain)" if is_maintain else "Perseus context renderer"
    )
    timer_desc = (
        "Perseus memory hygiene timer" if is_maintain else "Perseus context render timer"
    )

    raw_interval = getattr(args, "interval", None)
    if raw_interval is None:
        raw_interval = f"{_hygiene_schedule_minutes(cfg)}m" if is_maintain else "5m"
    try:
        interval = _parse_systemd_interval(raw_interval)
    except ValueError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    launcher, stable = _perseus_launcher()
    exec_start = " ".join(launcher + job_tokens)

    service_content = SYSTEMD_SERVICE_TEMPLATE.format(
        description=service_desc, exec_start=exec_start
    )
    timer_content = SYSTEMD_TIMER_TEMPLATE.format(
        description=timer_desc, interval=interval, unit=unit
    )
    if not stable:
        print("# ⚠ Could not find a stable `perseus` launcher (~/.local/bin/perseus or on PATH);", file=sys.stderr)
        print("#   ExecStart uses a version-specific path that may go stale after a Python upgrade.", file=sys.stderr)

    if getattr(args, "install", False):
        unit_dir = Path.home() / ".config" / "systemd" / "user"
        unit_dir.mkdir(parents=True, exist_ok=True)
        service_path = unit_dir / f"{unit}.service"
        timer_path = unit_dir / f"{unit}.timer"
        service_path.write_text(service_content, encoding="utf-8")
        timer_path.write_text(timer_content, encoding="utf-8")
        print(f"✔ Wrote {service_path}")
        print(f"✔ Wrote {timer_path}")
        print()
        print("Next steps:")
        print("  systemctl --user daemon-reload")
        print(f"  systemctl --user enable {unit}.timer")
        print(f"  systemctl --user start {unit}.timer")
        if getattr(args, "enable", False):
            for cmd in (
                ["systemctl", "--user", "daemon-reload"],
                ["systemctl", "--user", "enable", f"{unit}.timer"],
                ["systemctl", "--user", "start", f"{unit}.timer"],
            ):
                try:
                    subprocess.run(cmd, check=False)
                except Exception as exc:
                    print(f"> ⚠ {' '.join(cmd)} failed: {exc}")
        return

    # Default: print both unit files to stdout, separated
    print(f"# ~/.config/systemd/user/{unit}.service")
    print(service_content)
    print(f"# ~/.config/systemd/user/{unit}.timer")
    print(timer_content)


# ──────────────────────── Windows Task Scheduler (#694) ──────────────────────

def _schtasks_schedule(every_minutes: int) -> list:
    """schtasks trigger args for an every-N-minutes cadence.

    schtasks /SC MINUTE caps /MO at 1439, so daily-or-slower cadences map to
    /SC DAILY (at 03:00, matching the cron backend's off-hours choice).
    """
    if every_minutes >= 1440:
        days = max(1, every_minutes // 1440)
        return ["/SC", "DAILY", "/MO", str(days), "/ST", "03:00"]
    return ["/SC", "MINUTE", "/MO", str(every_minutes)]


def _schtasks_tr(tokens: list) -> str:
    """Quote a /TR command string (paths with spaces)."""
    return " ".join(f'"{t}"' if " " in t else t for t in tokens)


def cmd_schtasks(args, cfg):
    """#694: schedule a Perseus job via the native Windows Task Scheduler.

    Fills the platform gap the other backends leave: cron/launchd/systemd
    have zero coverage on native Windows, which is exactly where the
    hands-off hygiene persona lives. Task names parallel the POSIX tags:
    ``Perseus\\hygiene`` (+ ``Perseus\\hygiene-vacuum`` weekly companion)
    and ``Perseus\\render-<stem>``.
    """
    if sys.platform != "win32":
        print("Error: `perseus schtasks` is only supported on Windows.", file=sys.stderr)
        sys.exit(1)

    job_tokens, tag, stem = _resolve_job(args, cfg)
    is_maintain = tag == "perseus-hygiene"
    launcher, stable = _perseus_launcher()
    tr_cmd = _schtasks_tr(launcher + job_tokens)

    raw_every = getattr(args, "every", None)
    if raw_every is None:
        raw_every = _hygiene_schedule_minutes(cfg) if is_maintain else 5
    try:
        every = int(raw_every)
    except (TypeError, ValueError):
        print(f"Error: --every must be an integer (got {raw_every!r})", file=sys.stderr)
        sys.exit(1)
    if every <= 0:
        print("Error: --every must be > 0", file=sys.stderr)
        sys.exit(1)

    task_name = "Perseus\\hygiene" if is_maintain else f"Perseus\\render-{stem}"
    commands = [
        ["schtasks", "/Create", "/TN", task_name, "/TR", tr_cmd] + _schtasks_schedule(every)
    ]
    if is_maintain:
        hygiene = (cfg or {}).get("hygiene", {}) if isinstance(cfg, dict) else {}
        try:
            vacuum_runs = int(hygiene.get("vacuum_every_runs", 7) or 0)
        except (TypeError, ValueError):
            vacuum_runs = 7
        if vacuum_runs > 0:
            # Same stateless-scheduler reasoning as the cron backend: an
            # explicit weekly VACUUM task replaces an every-Nth-run counter.
            commands.append([
                "schtasks", "/Create", "/TN", "Perseus\\hygiene-vacuum",
                "/TR", tr_cmd + " --vacuum", "/SC", "WEEKLY", "/D", "SUN", "/ST", "03:00",
            ])

    if not stable:
        print("# ⚠ Could not find a stable `perseus` launcher (~/.local/bin/perseus or on PATH);")
        print("#   the task uses a version-specific path that may go stale after a Python upgrade.")

    if not getattr(args, "install", False):
        print("# Run these to install the Windows Scheduled Task(s):")
        for c in commands:
            print("  " + " ".join(f'"{t}"' if (" " in t and not t.startswith('"')) else t for t in c))
        print()
        print("Or install automatically with: perseus schtasks ... --install")
        return

    for c in commands:
        name = c[c.index("/TN") + 1]
        probe = subprocess.run(["schtasks", "/Query", "/TN", name],
                               capture_output=True, text=True, check=False)
        if probe.returncode == 0:
            print(f'> ⚠ Task {name} already exists. Remove it first: schtasks /Delete /TN "{name}" /F')
            sys.exit(1)
        proc = subprocess.run(c, capture_output=True, text=True, check=False)
        if proc.returncode != 0:
            print(f"Error: schtasks /Create failed: {(proc.stderr or proc.stdout).strip()}",
                  file=sys.stderr)
            sys.exit(1)
        print(f"✔ Created scheduled task {name}")
    print()
    print(f'Verify with: schtasks /Query /TN "{task_name}"')
    print(f'Remove with: perseus schtasks uninstall --job {getattr(args, "job", "render")}')


def cmd_schtasks_uninstall(args, cfg):
    """Remove Perseus Windows Scheduled Tasks (render by source, or hygiene)."""
    if sys.platform != "win32":
        print("Error: `perseus schtasks` is only supported on Windows.", file=sys.stderr)
        sys.exit(1)
    job = getattr(args, "job", "render") or "render"
    if job == "maintain":
        names = ["Perseus\\hygiene", "Perseus\\hygiene-vacuum"]
    else:
        if not getattr(args, "source", None):
            print("Error: removing a render task requires the source path.", file=sys.stderr)
            sys.exit(1)
        stem = Path(args.source).expanduser().resolve().stem
        names = [f"Perseus\\render-{stem}"]
    removed = 0
    for name in names:
        proc = subprocess.run(["schtasks", "/Delete", "/TN", name, "/F"],
                              capture_output=True, text=True, check=False)
        if proc.returncode == 0:
            print(f"✔ Removed scheduled task {name}")
            removed += 1
    if removed == 0:
        print("No matching scheduled task found.")


def cmd_launchd_uninstall(args, cfg):
    """Remove a Perseus LaunchAgent plist."""
    if sys.platform != "darwin":
        print("Error: `perseus launchd` is only supported on macOS.", file=sys.stderr)
        sys.exit(1)
    launch_agents = Path.home() / "Library" / "LaunchAgents"
    label = args.label
    plist_path = launch_agents / f"{label}.plist"
    if not plist_path.exists():
        print(f"Error: {plist_path} does not exist.", file=sys.stderr)
        sys.exit(1)
    # Unload first if loaded
    import subprocess as _sp
    _sp.run(["launchctl", "unload", str(plist_path)], capture_output=True)
    plist_path.unlink()
    print(f"✔ Removed LaunchAgent: {plist_path}")


def cmd_cron_uninstall(args, cfg):
    """Remove a Perseus crontab entry — render entries by source path, or the
    hygiene entries (``--job maintain``) by their ``# perseus-hygiene`` tag."""
    import subprocess as _sp
    job = getattr(args, "job", "render") or "render"
    try:
        result = _sp.run(["crontab", "-l"], capture_output=True, text=True)
        if result.returncode != 0:
            print("No crontab found.")
            return
        lines = result.stdout.split("\n")
        if job == "maintain":
            # Drops the nightly entry AND its weekly -vacuum companion.
            filtered = [l for l in lines if "# perseus-hygiene" not in l]
            removed_what = "the perseus-hygiene entries"
        else:
            if not getattr(args, "source", None):
                print("Error: removing a render entry requires the source path.", file=sys.stderr)
                sys.exit(1)
            source = Path(args.source).expanduser().resolve()
            marker = f"perseus render {source}"
            filtered = [l for l in lines if marker not in l]
            removed_what = f"the render entry for {source}"
        if len(filtered) == len(lines):
            print("No matching crontab entry found.")
            return
        _sp.run(["crontab", "-"], input="\n".join(filtered) + "\n", text=True)
        print(f"✔ Removed {removed_what}")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def cmd_systemd_uninstall(args, cfg):
    """Remove render or hygiene user-space systemd units."""
    if sys.platform == "darwin" or sys.platform == "win32":
        print("Error: `perseus systemd` is only supported on Linux.", file=sys.stderr)
        sys.exit(1)
    job = getattr(args, "job", "render") or "render"
    if job == "maintain":
        label = "perseus-hygiene"
    else:
        if not getattr(args, "source", None):
            print("Error: removing a render unit requires the source path.", file=sys.stderr)
            sys.exit(1)
        source_path = Path(args.source).expanduser().resolve()
        label = f"perseus-render-{source_path.stem}"
    user_units = Path.home() / ".config" / "systemd" / "user"
    timer_path = user_units / f"{label}.timer"
    service_path = user_units / f"{label}.service"
    import subprocess as _sp
    for unit_name in (f"{label}.timer", f"{label}.service"):
        _sp.run(["systemctl", "--user", "stop", unit_name], capture_output=True)
    for p in [timer_path, service_path]:
        if p.exists():
            p.unlink()
            print(f"✔ Removed: {p}")
    _sp.run(["systemctl", "--user", "daemon-reload"], capture_output=True)
    print(f"Run: systemctl --user stop {label}.timer  # if still running")
# ───────────────────────────── Cited synthesis ───────────────────────────────

def _synthesis_rel_label(path: Path, workspace: Path) -> str:
    try:
        return str(path.relative_to(workspace))
    except ValueError:
        return str(path)


def _resolve_synthesis_source(ref: str, workspace: Path, cfg: dict) -> tuple[Path | None, str | None]:
    raw = Path(ref).expanduser()
    path = raw.resolve() if raw.is_absolute() else (workspace / raw).resolve()
    if not path.exists():
        return None, f"source not found: {ref}"
    if path.is_dir():
        return None, f"source is a directory: {ref}"
    if not cfg.get("render", {}).get("allow_outside_workspace", False):
        try:
            path.relative_to(workspace)
        except ValueError:
            return None, f"source outside workspace: {path}"
    return path, None


def _load_synthesis_sources(refs: list[str], workspace: Path, cfg: dict) -> tuple[list[dict], list[str]]:
    sources: list[dict] = []
    errors: list[str] = []
    max_source_bytes = int(cfg.get("generation", {}).get("max_source_bytes", 12000))
    for index, ref in enumerate(refs, start=1):
        path, error = _resolve_synthesis_source(ref, workspace, cfg)
        if error or path is None:
            errors.append(error or f"invalid source: {ref}")
            continue
        # #587 item 1: guard the read per-source. Permission-denied, Windows
        # file locks, or check-to-read deletion must accumulate into errors
        # (the function's design) instead of crashing cmd_synthesize.
        try:
            text = path.read_text(errors="replace", encoding="utf-8")
        except OSError as exc:
            errors.append(f"could not read source: {ref} ({exc})")
            continue
        truncated = False
        # #587 item 3: enforce the budget in BYTES, not characters — multibyte
        # sources previously exceeded max_source_bytes by up to 4x.
        if max_source_bytes > 0:
            encoded = text.encode("utf-8")
            if len(encoded) > max_source_bytes:
                # errors="ignore" drops a partial trailing multibyte sequence
                # cleanly instead of raising or emitting U+FFFD.
                text = encoded[:max_source_bytes].decode("utf-8", errors="ignore")
                truncated = True
        lines = text.splitlines()
        sources.append({
            "id": f"src{index}",
            "path": str(path),
            "label": _synthesis_rel_label(path, workspace),
            "text": text,
            "lines": lines,
            "line_count": len(lines),
            "truncated": truncated,
        })
    return sources, errors


def _numbered_source_excerpt(source: dict) -> str:
    lines = source.get("lines", [])
    body = "\n".join(f"{idx}: {line}" for idx, line in enumerate(lines, start=1))
    suffix = "\n[truncated]" if source.get("truncated") else ""
    return f"### {source['id']} {source['label']}\n{body}{suffix}"


def build_synthesis_prompt(question: str, sources: list[dict], max_claims: int) -> str:
    source_blocks = "\n\n".join(_numbered_source_excerpt(source) for source in sources)
    return "\n".join([
        "You are drafting cited synthesis claims for Perseus.",
        "Perseus is a resolver first. You are a drafter, not an authority.",
        "",
        "Rules:",
        "- Return JSON only.",
        "- Do not include uncited claims.",
        "- Every claim must cite at least one exact quote from the source lines.",
        "- If the sources do not support a claim, omit it.",
        "- Prefer cross-source synthesis over obvious restatement.",
        f"- Return at most {max_claims} claims.",
        "",
        "JSON shape:",
        '{"claims":[{"text":"...","citations":[{"source_id":"src1","line_start":1,"line_end":3,"quote":"exact source quote"}]}]}',
        "",
        f"Question: {question}",
        "",
        "Sources:",
        source_blocks,
    ])


def _extract_json_object(text: str) -> tuple[object | None, str | None]:
    stripped = text.strip()
    if stripped.startswith("```"):
        stripped = re.sub(r"^```(?:json)?\s*", "", stripped, flags=re.IGNORECASE)
        stripped = re.sub(r"\s*```$", "", stripped)
    try:
        return json.loads(stripped), None
    except json.JSONDecodeError:
        start = stripped.find("{")
        end = stripped.rfind("}")
        if start >= 0 and end > start:
            try:
                return json.loads(stripped[start:end + 1]), None
            except json.JSONDecodeError as exc:
                return None, f"could not parse JSON response: {exc}"
        return None, "could not parse JSON response"


def _citation_window(source: dict, start: int, end: int) -> str | None:
    lines = source.get("lines", [])
    if start < 1 or end < start or end > len(lines):
        return None
    return "\n".join(lines[start - 1:end])


def build_consistency_prompt(sources: list[dict], max_claims: int) -> str:
    """Build a prompt focused on detecting cross-source disagreements."""
    source_blocks = "\n\n".join(_numbered_source_excerpt(source) for source in sources)
    return "\n".join([
        "You are auditing cross-source consistency for a software project.",
        "Perseus is a resolver first. You are a drafter, not an authority.",
        "",
        "Rules:",
        "- Return JSON only.",
        "- Do not include uncited claims.",
        "- Every claim must cite at least one exact quote from the source lines.",
        "- Report disagreements, drift, and contradictions between sources.",
        "- Flag: current phase/status inconsistencies, version mismatches, doc/code contradictions,",
        "  task-file status that conflicts with roadmap or handoff, outdated README claims.",
        "- If all sources are consistent on a topic, do not generate claims about it.",
        "- Use 'conflicts' for disagreements between sources; use 'claims' for synthesized findings.",
        f"- Return at most {max_claims} items across both arrays.",
        "",
        "JSON shape:",
        '{"claims":[{"text":"...","citations":[{"source_id":"src1","line_start":1,"line_end":3,"quote":"exact source quote"}]}],',
        '"conflicts":[{"description":"...","sources":[{"source_id":"src1","line_start":1,"line_end":2,"quote":"..."},',
        '{"source_id":"src2","line_start":5,"line_end":5,"quote":"..."}]}]}',
        "",
        "Sources:",
        source_blocks,
    ])


def _validate_consistency_conflicts(raw: object, sources: list[dict], max_items: int) -> tuple[list[dict], list[dict]]:
    """Validate the 'conflicts' array from a consistency-mode response."""
    source_by_id = {source["id"]: source for source in sources}
    conflicts_raw = raw.get("conflicts", []) if isinstance(raw, dict) else []
    if not isinstance(conflicts_raw, list):
        return [], [{"description": "", "reason": "conflicts must be a list"}]

    accepted: list[dict] = []
    dropped: list[dict] = []
    for entry in conflicts_raw[:max_items]:
        if not isinstance(entry, dict):
            dropped.append({"description": "", "reason": "conflict entry must be an object"})
            continue
        description = str(entry.get("description", "")).strip()
        sources_raw = entry.get("sources", [])
        valid_sources: list[dict] = []
        if isinstance(sources_raw, list):
            for ref in sources_raw:
                if not isinstance(ref, dict):
                    continue
                source_id = str(ref.get("source_id", "")).strip()
                source = source_by_id.get(source_id)
                quote = str(ref.get("quote", "")).strip()
                try:
                    line_start = int(ref.get("line_start"))
                    line_end = int(ref.get("line_end", line_start))
                except (TypeError, ValueError):
                    continue
                if not source or not quote:
                    continue
                window = _citation_window(source, line_start, line_end)
                if window is None or quote not in window:
                    continue
                valid_sources.append({
                    "source_id": source_id,
                    "path": source["path"],
                    "label": source["label"],
                    "line_start": line_start,
                    "line_end": line_end,
                    "quote": quote,
                })
        if description and len(valid_sources) >= 2:
            accepted.append({"description": description, "sources": valid_sources})
        elif description and len(valid_sources) == 1:
            # Accept single-source conflict reports (e.g. internal inconsistency flagged with one cite)
            accepted.append({"description": description, "sources": valid_sources})
        else:
            dropped.append({
                "description": description,
                "reason": "no valid cited sources" if description else "empty description",
            })
    return accepted, dropped


def _validate_synthesis_claims(raw: object, sources: list[dict], max_claims: int) -> tuple[list[dict], list[dict]]:
    source_by_id = {source["id"]: source for source in sources}
    claims_raw = raw.get("claims", []) if isinstance(raw, dict) else []
    if not isinstance(claims_raw, list):
        return [], [{"text": "", "reason": "claims must be a list", "citations": []}]

    accepted: list[dict] = []
    dropped: list[dict] = []
    for claim_raw in claims_raw[:max_claims]:
        if not isinstance(claim_raw, dict):
            dropped.append({"text": "", "reason": "claim must be an object", "citations": []})
            continue
        text = str(claim_raw.get("text", "")).strip()
        citations_raw = claim_raw.get("citations", [])
        valid_citations: list[dict] = []
        if isinstance(citations_raw, list):
            for citation in citations_raw:
                if not isinstance(citation, dict):
                    continue
                source_id = str(citation.get("source_id", "")).strip()
                source = source_by_id.get(source_id)
                quote = str(citation.get("quote", "")).strip()
                try:
                    line_start = int(citation.get("line_start"))
                    line_end = int(citation.get("line_end", line_start))
                except (TypeError, ValueError):
                    continue
                if not source or not quote:
                    continue
                window = _citation_window(source, line_start, line_end)
                if window is None or quote not in window:
                    continue
                valid_citations.append({
                    "source_id": source_id,
                    "path": source["path"],
                    "label": source["label"],
                    "line_start": line_start,
                    "line_end": line_end,
                    "quote": quote,
                })
        if text and valid_citations:
            accepted.append({"text": text, "citations": valid_citations})
        else:
            dropped.append({
                "text": text,
                "reason": "no valid citations" if text else "empty claim text",
                "citations": citations_raw if isinstance(citations_raw, list) else [],
            })
    return accepted, dropped


def synthesize_question(
    question: str,
    source_refs: list[str],
    cfg: dict,
    workspace: Path,
    llm: str | None = None,
    model: str | None = None,
    model_url: str | None = None,
    enable_generation: bool = False,
    consistency_mode: bool = False,
) -> tuple[dict, int]:
    sources, source_errors = _load_synthesis_sources(source_refs, workspace, cfg)
    generation_cfg = cfg.get("generation", {})
    max_claims = int(generation_cfg.get("max_claims", 6))
    source_summary = [
        {
            "id": source["id"],
            "path": source["path"],
            "label": source["label"],
            "line_count": source["line_count"],
            "truncated": source["truncated"],
        }
        for source in sources
    ]
    result: dict = {
        "version": "phase15b-cited-synthesis-v2" if consistency_mode else "phase15a-cited-synthesis-v1",
        "question": question,
        "consistency_mode": consistency_mode,
        "generated": False,
        "claims": [],
        "dropped_claims": [],
        "conflicts": [],
        "dropped_conflicts": [],
        "source_errors": source_errors,
        "sources": source_summary,
        "guardrails": {
            "citation_required": True,
            "exact_quote_required": True,
            "uncited_claims_dropped": True,
            "model_failure_leaves_render_unchanged": True,
        },
        "model": {"provider": None, "model": None},
        "prompt": "",
    }
    if source_errors or not sources:
        return result, 1

    if consistency_mode:
        prompt = build_consistency_prompt(sources, max_claims)
    else:
        prompt = build_synthesis_prompt(question, sources, max_claims)
    result["prompt"] = prompt
    # Perseus runs no inference of its own (observe model): @synthesize
    # assembles the cited-synthesis prompt (sources + citation scaffolding) and
    # returns it for the host agent to answer with whatever model it already
    # uses. The `llm`/`enable_generation` arguments are accepted for call-site
    # compatibility but Perseus no longer calls a provider itself; when they are
    # set we surface the prompt plus a note rather than generating in-process.
    if llm:
        result["note"] = ("in-process generation removed — Perseus returns the "
                          "synthesis prompt for the host agent to answer")
    return result, 0


def format_synthesis_human(result: dict) -> str:
    lines = [f"Cited synthesis: {result['question']}"]
    if result.get("consistency_mode"):
        lines[0] = "Cross-source consistency report"
    if result.get("source_errors"):
        lines.append("")
        lines.append("Source errors:")
        for error in result["source_errors"]:
            lines.append(f"- {error}")
        return "\n".join(lines)
    lines.append("Sources:")
    for source in result.get("sources", []):
        suffix = " (truncated)" if source.get("truncated") else ""
        lines.append(f"- {source['id']} {source['label']} ({source['line_count']} lines){suffix}")
    if result.get("error"):
        lines.append("")
        lines.append(f"> Warning: {result['error']}")
    if not result.get("generated"):
        lines.append("")
        lines.append("Generation was not run. Prompt:")
        lines.append("")
        lines.append(result.get("prompt", ""))
        return "\n".join(lines)

    lines.append("")
    if not result.get("claims") and not result.get("conflicts"):
        lines.append("_No cited claims or conflicts survived validation._")
    for idx, claim in enumerate(result.get("claims", []), start=1):
        lines.append(f"{idx}. {claim['text']}")
        for citation in claim["citations"]:
            label = citation["label"]
            start = citation["line_start"]
            end = citation["line_end"]
            line_ref = f"{start}" if start == end else f"{start}-{end}"
            lines.append(f"   - {label}:{line_ref} `{citation['quote']}`")
    conflicts = result.get("conflicts", [])
    if conflicts:
        lines.append("")
        lines.append("Source disagreements:")
        for idx, conflict in enumerate(conflicts, start=1):
            lines.append(f"{idx}. ⚠ {conflict['description']}")
            for ref in conflict["sources"]:
                label = ref["label"]
                start = ref["line_start"]
                end = ref["line_end"]
                line_ref = f"{start}" if start == end else f"{start}-{end}"
                lines.append(f"   - {label}:{line_ref} `{ref['quote']}`")
    dropped = result.get("dropped_claims", [])
    dropped_conflicts = result.get("dropped_conflicts", [])
    if dropped:
        lines.append("")
        lines.append(f"Dropped uncited/invalid claims: {len(dropped)}")
    if dropped_conflicts:
        lines.append(f"Dropped uncited/invalid conflicts: {len(dropped_conflicts)}")
    return "\n".join(lines)


def cmd_synthesize(args, cfg) -> int:
    workspace = Path(args.workspace).expanduser().resolve() if getattr(args, "workspace", None) else Path.cwd().resolve()
    cfg = load_config(workspace)
    result, code = synthesize_question(
        args.question,
        args.source,
        cfg,
        workspace,
        llm=getattr(args, "llm", None),
        model=getattr(args, "model", None),
        model_url=getattr(args, "model_url", None),
        enable_generation=getattr(args, "enable_generation", False),
        consistency_mode=getattr(args, "consistency_mode", False),
    )
    # task-46: redact synthesis result before output. JSON-mode caller can
    # inspect `result["redaction"]` to see counts without seeing secrets.
    if isinstance(result, dict):
        result, rep = redact_value(result, cfg)
        result["redaction"] = {
            "enabled": rep.get("enabled", True),
            "total": rep.get("total", 0),
            "counts": rep.get("counts", {}),
        }
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2))
    else:
        print(format_synthesis_human(result))
    return code
# ─────────────────────────────── Self-Update ──────────────────────────────────

# ── GPG signature verification ──────────────────────────────────────────────
# Trusted public key fingerprint for Perseus releases.
# To generate: gpg --detach-sign --armor perseus.py
# To verify:   gpg --verify perseus.py.asc perseus.py
PERSEUS_GPG_FINGERPRINT = None  # Set to your GPG key fingerprint (40-char hex)

PERSEUS_GPG_FINGERPRINT_SHORT = None  # Set to your GPG key ID (16-char hex)


def _gpg_verify_signature(repo: Path, args, cfg: dict | None = None) -> tuple[bool, str]:
    """Verify the GPG signature on the current HEAD or latest tag.

    Returns (verified: bool, message: str).
    Requires git and gpg to be installed. Non-fatal on missing tools —
    just reports that verification was skipped.
    """
    update_cfg = {}
    try:
        update_cfg = (cfg or {}).get("update", {}) or {}
    except Exception:
        pass
    skip = getattr(args, "skip_signature_check", False)
    if skip:
        return True, "signature check skipped (--skip-signature-check)"

    fingerprint = update_cfg.get("gpg_fingerprint") or PERSEUS_GPG_FINGERPRINT
    auto_enabled = bool(update_cfg.get("auto", False))
    if not fingerprint:
        # 2026-07-05 security review: previously this ALWAYS returned True, so
        # `update --apply` pulled+ran whatever origin/main held with zero
        # verification. Unattended (auto) updates must NOT run unverified; a
        # manual update may proceed but is loudly flagged as unverified.
        if auto_enabled:
            return False, (
                "unattended auto-update requires update.gpg_fingerprint to be set "
                "(refusing to pull unverified code); configure it or disable update.auto"
            )
        return True, (
            "⚠ no GPG fingerprint configured — update is NOT signature-verified "
            "(set update.gpg_fingerprint to enforce)"
        )

    # A fingerprint IS configured → verification is REQUIRED. Every gap below now
    # fails CLOSED (was fail-open); use --skip-signature-check to bypass explicitly.
    import subprocess as _sp

    # Check for gpg binary
    try:
        _sp.run(["gpg", "--version"], capture_output=True, check=True)
    except Exception:
        return False, (
            "gpg not found but update.gpg_fingerprint is set — cannot verify "
            "(install gpg, or pass --skip-signature-check to override)"
        )

    # Verify HEAD's signature against the local keyring AND require it to be the
    # configured fingerprint (git verify-commit alone trusts any keyring key).
    try:
        result = _sp.run(
            ["git", "verify-commit", "--raw", "HEAD"],
            capture_output=True, text=True, timeout=30, cwd=str(repo),
        )
        output = (result.stdout + result.stderr).strip()
        if result.returncode != 0:
            return False, f"GPG verification failed (commit unsigned or bad signature): {output[:200]}"
        fp_norm = fingerprint.replace(" ", "").upper()
        if fp_norm and fp_norm not in output.replace(" ", "").upper():
            return False, (
                f"GPG signature is valid but NOT from the configured fingerprint "
                f"{fingerprint} — refusing to apply"
            )
        return True, f"GPG signature verified against {fingerprint}"
    except _sp.TimeoutExpired:
        return False, "GPG verification timed out — refusing to apply unverified update"
    except Exception as exc:
        return False, f"GPG verification error — refusing to apply: {exc}"


def cmd_update(args, cfg) -> int:
    """Self-update: check for or apply Perseus updates from git.

    Perseus is installed in editable mode — updating the source via git pull
    automatically updates the CLI. No reinstall needed.
    """
    import subprocess as _sp

    update_cfg = cfg.get("update", {})
    repo_path_str = update_cfg.get("repo_path", "")
    branch = update_cfg.get("branch", "main")

    # ── --auto toggle ──────────────────────────────────────────────────────
    auto_val = getattr(args, "auto", None)
    if auto_val is not None:
        return _toggle_auto_update(auto_val, cfg)

    # ── Find the repo ──────────────────────────────────────────────────────
    repo = None
    if repo_path_str:
        repo = Path(repo_path_str).resolve()
    if not repo or not (repo / ".git").exists():
        repo = _find_perseus_repo()
    if not repo or not (repo / ".git").exists():
        print("Error: Perseus git repository not found.", file=sys.stderr)
        print("  Set update.repo_path in ~/.perseus/config.yaml", file=sys.stderr)
        print("  Clone: git clone https://github.com/Perseus-Computing-LLC/perseus.git", file=sys.stderr)
        return 1

    os.chdir(str(repo))

    # ── Fetch ──────────────────────────────────────────────────────────────
    print(f"Fetching origin/{branch} …")
    try:
        _sp.run(["git", "fetch", "origin", branch],
                check=True, capture_output=True, text=True)
    except _sp.CalledProcessError as e:
        print(f"Error: git fetch failed: {e.stderr.strip()}", file=sys.stderr)
        return 1

    # ── Compare local vs remote ────────────────────────────────────────────
    def _git(args_list):
        return _sp.run(["git"] + args_list, capture_output=True,
                       text=True).stdout.strip()

    local = _git(["rev-parse", "HEAD"])
    remote = _git(["rev-parse", f"origin/{branch}"])

    if local == remote:
        print(f"✓ Perseus is up to date ({local[:8]} on {branch})")
        return 0

    # Determine relationship: is local ahead, behind, or diverged?
    merge_base = _git(["merge-base", local, remote])
    if merge_base == remote:
        # local is ahead of or same as remote — nothing to pull
        print(f"✓ Perseus is up to date (local is ahead of origin/{branch})")
        print(f"  Local:  {local[:8]}")
        print(f"  Remote: {remote[:8]} (behind)")
        return 0
    elif merge_base == local:
        # local is behind remote — updates available
        pass
    else:
        # Diverged — both have commits the other doesn't
        print(f"⚠ Local and origin/{branch} have diverged.", file=sys.stderr)
        print(f"  Local:  {local[:8]}", file=sys.stderr)
        print(f"  Remote: {remote[:8]}", file=sys.stderr)
        print("  Fast-forward not possible. Manual merge required.", file=sys.stderr)
        return 1

    # ── Show available updates ─────────────────────────────────────────────
    log = _git(["log", "--oneline", f"{local}..{remote}"])
    commits = log.split("\n") if log else []
    count = len(commits)

    print(f"\n{count} commit(s) behind origin/{branch}:")
    print(f"  Installed: {local[:8]}")
    print(f"  Latest:    {remote[:8]}")
    print()
    for line in commits:
        print(f"  {line}")
    print()

    apply_update = getattr(args, "apply", False)
    check_only = getattr(args, "check", False)

    if apply_update:
        # GPG signature verification before applying update
        verified, gpg_msg = _gpg_verify_signature(repo, args, cfg)
        if not verified:
            print(f"⚠ GPG signature verification FAILED: {gpg_msg}", file=sys.stderr)
            print("  Use --skip-signature-check to bypass.", file=sys.stderr)
            return 1
        if "verification skipped" in gpg_msg.lower():
            pass  # Non-fatal
        print(f"✓ GPG: {gpg_msg}")

        print("Applying update …")
        try:
            result = _sp.run(
                ["git", "pull", "--ff-only", "origin", branch],
                capture_output=True, text=True, check=True,
            )
            print(result.stdout.strip())
            new_local = _git(["rev-parse", "HEAD"])
            print(f"✓ Updated to {new_local[:8]}")
        except _sp.CalledProcessError as e:
            print(f"Error: git pull failed: {e.stderr.strip()}", file=sys.stderr)
            print(f"  Try: cd {repo} && git pull --ff-only origin {branch}",
                  file=sys.stderr)
            return 1
    elif not check_only:
        print("To apply:  perseus update --apply")
        print("Dry run:   perseus update --check")
        if not cfg.get("update", {}).get("auto", False):
            print("Auto:      perseus update --auto on")

    return 0


def _find_perseus_repo():
    """Locate the Perseus git repository from the installed package."""
    import subprocess as _sp
    # Check pip show for editable install location
    try:
        result = _sp.run(["pip", "show", "perseus-ctx"],
                         capture_output=True, text=True)
        for line in result.stdout.split("\n"):
            if line.startswith("Editable project location:"):
                loc = line.split(":", 1)[1].strip()
                p = Path(loc)
                if (p / ".git").exists():
                    return p
    except Exception:
        pass
    # Fallback: common paths
    for c in [Path("/workspace/perseus")]:
        if (c / ".git").exists():
            return c
    return None


def _toggle_auto_update(value, cfg):
    """Persist update.auto on/off in the global config file."""
    config_path = Path(os.environ.get("PERSEUS_HOME",
                       Path.home() / ".perseus")) / "config.yaml"
    val = value.strip().lower()
    if val in ("on", "true", "1", "yes"):
        enabled = True
    elif val in ("off", "false", "0", "no"):
        enabled = False
    else:
        print(f"Error: '{value}' — use 'on' or 'off'.", file=sys.stderr)
        return 1

    # Read existing config, preserving comments is hard so just re-dump
    if config_path.exists():
        with open(config_path, encoding='utf-8') as f:
            data = yaml.safe_load(f) or {}
    else:
        data = {}
    if not isinstance(data, dict):
        data = {}

    cfg2 = copy.deepcopy(data)
    if "update" not in cfg2:
        cfg2["update"] = {}
    cfg2["update"]["auto"] = enabled

    if cfg2 != data:
        config_path.parent.mkdir(parents=True, exist_ok=True)
        with open(config_path, "w", encoding="utf-8") as f:
            yaml.safe_dump(cfg2, f, default_flow_style=False, sort_keys=False)

    status = "ON" if enabled else "OFF"
    print(f"Auto-update: {status}")
    print(f"  Config: {config_path}")
    if enabled:
        print("  Perseus will check for updates when invoked with --apply.")
    return 0
# ──────────────────────────────── Quickstart ──────────────────────────────────

QUICKSTART_CONTEXT_TEMPLATE = """\
@perseus

@prompt
This document was rendered by Perseus at session start. Values below reflect
the workspace at render time — prefer this snapshot over re-verifying services,
re-scanning skills, or re-reading session history, and start work promptly.
When a value is stale, surprising, or load-bearing for a decision, verify it
with live tools; rendered context is a snapshot, not ground truth.

Note: this content is already part of your context — you do not need to search
for or re-read AGENTS.md on disk (the disk copy is an earlier snapshot of the
same render). Weigh any injected memory below by its relevance to the current
task, not by the fact that it was injected.
@end

## Memory Gate — STOP. Answer these three questions before saving ANYTHING.

Before storing a fact in the `memory` tool, verify ALL three:

1. **Will this fact still be relevant in 2+ sessions?** If NO → do NOT save.
2. **Is this a procedure, workflow, or how-to?** If YES → use `skill_manage` (not memory).
3. **Could this be re-discovered in < 30 seconds?** If YES → do NOT save.

Only facts that pass ALL THREE gates belong in `memory` (2,200 char hard limit).
Everything else has a better home:
- 🔁 **Procedures** → `skill_manage` (create/update a skill)
- 🧠 **Cross-session context** → Perseus Vault (MCP `perseus_vault_remember` / `perseus_vault_recall`)
- 🚫 **Ephemeral state, one-time fixes, completed tasks** → discard

🚫 **Flat files (.txt, .json, .csv, .md) are BANNED as a memory backend.**

---

# Perseus Session Context — @date format="YYYY-MM-DD HH:mm z"

**Workspace:** `{workspace}`

---

## Workspace State

@query "git -C {workspace} log --oneline -5 2>/dev/null || echo '(no git repo)'"
@query "git -C {workspace} status --short 2>/dev/null || echo ''"

---

## Available Skills
@skills flag_stale=true

---

## Services
@services

---

## Project Memory (Perseus Vault)
@memory focus=recent ttl=300

---

## Persistent Memory (Perseus Vault)

> 💡 **Query tips:** FTS5 treats multi-word queries as exact phrases.
> Split long queries across multiple directives for better recall:
> ```text
> @memory mode=search query="short phrase" k=3
> @memory mode=search query="another topic" k=2
> ```
> Each sub-query is short enough to match effectively; the relay layer merges results.
> Falls back gracefully to local Perseus Vault FTS5 if Perseus Vault is unavailable.
> Requires `perseus_vault.enabled: true` in `.perseus/config.yaml`.

@memory mode=search query="{vault_query}" k=5
"""


def _quickstart_write_config(
    workspace: Path, with_memory: bool = False
) -> Path:
    """Write a minimal .perseus/config.yaml with safe defaults.

    Perseus runs no inference of its own (observe model), so no LLM backend is
    configured here — the host agent uses whatever model it already has.

    The memory connector is always wired (enabled) under the canonical
    ``perseus_vault:`` key with the ``perseus-vault`` binary (#665). No ``--db``
    argument is emitted: the Vault binary self-resolves its canonical default DB
    path, so omitting it eliminates path drift. ``with_memory`` controls whether
    the canonical connector is enabled in the generated configuration.
    """
    perseus_dir = workspace / ".perseus"
    perseus_dir.mkdir(parents=True, exist_ok=True)
    config_path = perseus_dir / "config.yaml"

    memory_key = "perseus_vault"
    memory_block = {
        "enabled": True,
        "transport": "stdio",
        "command": ["perseus-vault", "serve"],
    }

    config: dict = {
        "render": {
            "allow_query_shell": False,
            "cache_dir": str(perseus_dir / "cache"),
        },
        "permissions": {
            "profile": "balanced",
        },
        memory_key: memory_block,
    }

    with open(config_path, "w", encoding="utf-8") as f:
        yaml.safe_dump(config, f, sort_keys=False)
    return config_path


def cmd_quickstart(args, cfg) -> int:
    """`perseus quickstart` — one command from zero to working Perseus.

    Detects workspace, scaffolds .perseus/context.md, writes config,
    offers free LLM backend setup, and verifies everything works with
    a render + doctor run.
    """
    workspace_arg = getattr(args, "workspace", None)
    if workspace_arg:
        workspace = Path(workspace_arg).expanduser().resolve()
    else:
        workspace = Path.cwd().resolve()

    # Detect git repo root as workspace
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, cwd=str(workspace),
        )
        if result.returncode == 0:
            workspace = Path(result.stdout.strip()).resolve()
    except Exception:
        pass

    non_interactive = getattr(args, "non_interactive", False)
    with_memory = getattr(args, "with_memory", False)

    print(f"Perseus quickstart — v{_PERSEUS_VERSION}")
    print(f"Workspace: {workspace}")
    print()

    # Step 1: Scaffold context.md (idempotent — init handles that)
    perseus_dir = workspace / ".perseus"
    context_file = perseus_dir / "context.md"
    config_file = perseus_dir / "config.yaml"

    if context_file.exists():
        print(f"✓ Context file already exists: {context_file}")
    else:
        # Build a fake args namespace for cmd_init
        init_args = argparse.Namespace(
            workspace=str(workspace),
            force=False,
            profile=None,
            template=None,
            output=None,
            trust_profile=None,
            no_pack=True,
            list_templates=False,
            list_profiles=False,
        )
        cmd_init(init_args, cfg)
        print()

    # Step 2: Write config if missing
    if config_file.exists():
        print(f"✓ Config already exists: {config_file}")
    else:
        path = _quickstart_write_config(workspace, with_memory=with_memory)
        print(f"✓ Wrote config: {path}")
        print("  Memory connector wired under canonical `perseus_vault:` key")
        print()

    # Step 3: Reload config from workspace so permission profile is applied
    cfg = load_config(workspace)

    # ── Perseus Vault (memory) install & wiring check (#301, #663) ──
    #
    # quickstart always writes an enabled memory connector, but the binary
    # (Perseus Vault, a separate Rust build) is NOT bundled — so without this
    # check a user's memory block is silently empty. Detect the missing binary
    # and print a clear warning + copy-paste remediation. We never auto-download
    # or build the Rust binary silently (#663); the install is always an
    # explicit, operator-run command.
    try:
        mcfg = _resolve_vault_config(cfg) if cfg else {}
        if mcfg.get("enabled", True):
            command = mcfg.get("command", ["perseus-vault", "serve"])
            binary_path = _find_vault_binary(command)
            if binary_path is None:
                print("⚠ Perseus Vault (persistent memory engine) is configured but NOT installed.")
                print("  The memory block will be EMPTY until the binary is on PATH.")
                print(f"  → {MEMORY_INSTALL_REMEDIATION}")
                if with_memory:
                    print()
                    print("  --with-memory: connector config is wired; complete setup with the")
                    print("  install command above, then re-run `perseus doctor` to confirm.")
                print()
            else:
                print(f"✓ Perseus Vault binary found: {binary_path}")
                print()
    except Exception:
        pass

    # Step 4: Verify with a render
    text = context_file.read_text(errors="replace", encoding="utf-8")
    _stats = {"directive_count": 0, "cache_hits": 0, "cache_misses": 0}
    rendered = render_source(text, cfg, workspace, _stats=_stats)
    print(f"✓ Render verified — {_stats['directive_count']} directives resolved "
          f"({_stats['cache_hits']} cached, {_stats['cache_misses']} resolved)")
    # Be honest when the Workspace State section rendered as a gated-off warning
    # rather than live git output: the default config leaves shell `@query` off
    # (defense-in-depth), so a "verified" with an empty Workspace State would
    # otherwise look broken on the very first render.
    if "@query is disabled" in rendered or "PERSEUS_ALLOW_DANGEROUS" in rendered:
        print("  ⚠ The Workspace State section uses live shell `@query` (git status/log),")
        print("    which is OFF by default. To turn it on:")
        print("      1) set  render.allow_query_shell: true  in .perseus/config.yaml")
        print("      2) export PERSEUS_ALLOW_DANGEROUS=1")
        print("    Everything else in your context is already live.")
    print()

    # Step 5: Print next steps
    #
    # Emit hints with the invocation that actually works on THIS install
    # (#660): a bare ``perseus`` is dead advice for single-file / curl-install
    # users who have no console script on PATH. ``_perseus_command_string``
    # resolves to the entry point when available, else ``<python> <artifact>``.
    launcher = _perseus_command_string()
    print("Perseus ready! Next steps:")
    print(f"  {launcher} render {context_file}        — refresh context")
    print(f"  {launcher} serve --lsp --stdio          — start the LSP for your editor")
    print(f"  {launcher} suggest \"<task>\"             — get task suggestions")
    print(f"  {launcher} doctor --workspace {workspace}  — health check")
    print()

    return 0
# ═══════════════════════════════════════════════════════════════════════════════
# perseus knows — plain-language "what does my assistant know about me?" (#692)
#
# Everyday-user surface over the Vault: one friendly screen of what is
# currently held, grouped and trust-annotated, with a path to correct or
# forget anything wrong. CLI-only v1; the pure renderers are shared by the
# `/knows` serve endpoint (#695).
# ═══════════════════════════════════════════════════════════════════════════════

# Bucket mapping, from a live-store category dump (2026-07-07, 21 distinct
# categories over 1,328 entities): user, architecture, benchmark, checkpoint,
# communication, contribution, convention, conversation, correction, decision,
# devops, general, infrastructure, insight, integration, opportunity,
# perseus-computing, reference, session, task, test. Unknown categories fall
# back to the project bucket rather than being hidden.
_KNOWS_ABOUT_YOU_CATEGORIES = frozenset({
    "user", "identity", "preference", "preferences", "profile", "personal",
    "communication",
})
# Session flotsam: auto-captured summaries, not curated facts. Old ones are
# collapsed into a single count line so 1,000+ conversation entities can't
# drown the four real buckets.
_KNOWS_CONVERSATIONAL_CATEGORIES = frozenset({
    "conversation", "session", "checkpoint", "general",
})

_KNOWS_BUCKET_ABOUT_YOU = "About you"
_KNOWS_BUCKET_PROJECT = "Project facts & decisions"
_KNOWS_BUCKET_RECENT = "Recently learned"
_KNOWS_BUCKET_STALE = "Low confidence — might be stale"

_KNOWS_BUCKET_ORDER = [
    _KNOWS_BUCKET_ABOUT_YOU,
    _KNOWS_BUCKET_RECENT,
    _KNOWS_BUCKET_PROJECT,
    _KNOWS_BUCKET_STALE,
]

_KNOWS_LOW_CONFIDENCE_DECAY = 0.3   # below this Ebbinghaus score → stale bucket
_KNOWS_RECENT_DAYS = 7
_KNOWS_SHORT_ID_LEN = 8             # 4 chars collides at ~1.3k entities (#692)
_KNOWS_DEFAULT_LIMIT = 500
_KNOWS_ITEMS_PER_BUCKET = 8         # human view cap per bucket; --json is uncapped


def _knows_short_id(entity_id: str) -> str:
    """Stable short id: the hex part after the 'mem-' prefix, 8 chars."""
    raw = entity_id[4:] if entity_id.startswith("mem-") else entity_id
    return raw[:_KNOWS_SHORT_ID_LEN]


def _knows_resolve_id(hits: list, token: str) -> tuple[object | None, str]:
    """Resolve a user-typed id prefix git-style.

    Accepts the short id, any longer prefix, or the full id (with or without
    the 'mem-' prefix). Returns (hit, "") on a unique match, (None, reason)
    on no match or ambiguity — never guesses among several candidates.
    """
    tok = token.strip()
    if not tok:
        return None, "empty id"
    candidates = []
    for h in hits:
        bare = h.id[4:] if h.id.startswith("mem-") else h.id
        tok_bare = tok[4:] if tok.startswith("mem-") else tok
        if bare.startswith(tok_bare):
            candidates.append(h)
    if not candidates:
        return None, f"no memory matches id '{tok}' (run `perseus knows` to list ids)"
    if len(candidates) > 1:
        opts = ", ".join(_knows_short_id(c.id) for c in candidates[:6])
        return None, (
            f"id '{tok}' is ambiguous — {len(candidates)} matches ({opts}); "
            "give more characters"
        )
    return candidates[0], ""


def _knows_bucket(hit, now_ms: int) -> str:
    """Assign a hit to its display bucket (priority order matters).

    1. About-you categories always show under "About you" (a stale user fact
       still belongs with the user facts — it gets the ~stale marker there).
    2. Low decay → the stale bucket, so doubtful items are surfaced, not mixed
       in as confident knowledge.
    3. Learned within the last week → "Recently learned".
    4. Everything else → the project bucket (explicit fallback).
    """
    if hit.category in _KNOWS_ABOUT_YOU_CATEGORIES:
        return _KNOWS_BUCKET_ABOUT_YOU
    if hit.decay_score < _KNOWS_LOW_CONFIDENCE_DECAY:
        return _KNOWS_BUCKET_STALE
    age_ms = now_ms - (hit.created_at_unix_ms or 0)
    if age_ms <= _KNOWS_RECENT_DAYS * 86400 * 1000:
        return _KNOWS_BUCKET_RECENT
    return _KNOWS_BUCKET_PROJECT


def _knows_item(hit) -> dict:
    """Flatten a MemoryHit into the JSON/display item shape."""
    text = (hit.summary or hit.content or "").strip().replace("\n", " ")
    if len(text) > 110:
        text = text[:107] + "…"
    return {
        "id": hit.id,
        "short_id": _knows_short_id(hit.id),
        "category": hit.category,
        "key": hit.key,
        "type": getattr(hit.type, "value", str(hit.type)),
        "summary": text,
        "verified": bool(hit.verified),
        "decay_score": round(float(hit.decay_score), 3),
        "layer": getattr(hit.layer, "value", str(hit.layer)),
        "created_at_unix_ms": hit.created_at_unix_ms,
        "last_accessed_unix_ms": hit.last_accessed_unix_ms,
    }


def _knows_model(hits: list, stats: dict | None, limit: int) -> dict:
    """Build the renderer-agnostic model both the CLI and /knows (#695) use.

    Counts come from the Vault's active-only stats fields when the server has
    them (perseus-vault #493); `perseus_vault_stats.total_entities` is archived-
    inflated, so with an older server the headline falls back to the listing
    size and archived stays unknown rather than lying.
    """
    now = int(time.time() * 1000)
    buckets: dict[str, list[dict]] = {name: [] for name in _KNOWS_BUCKET_ORDER}
    old_conversational = 0
    for h in hits:
        bucket = _knows_bucket(h, now)
        if (bucket == _KNOWS_BUCKET_PROJECT
                and h.category in _KNOWS_CONVERSATIONAL_CATEGORIES):
            old_conversational += 1
            continue
        buckets[bucket].append(_knows_item(h))

    active = archived = None
    if isinstance(stats, dict) and "active_entities" in stats:
        active = stats.get("active_entities")
        archived = stats.get("archived_entities")

    truncated = len(hits) >= limit
    return {
        "active_entities": active,        # None = server predates the #493 split
        "archived_entities": archived,
        "listed": len(hits),
        "truncated": truncated,
        "buckets": buckets,
        "older_conversational": old_conversational,
        "bucket_order": list(_KNOWS_BUCKET_ORDER),
    }


def _knows_age(now_ms: int, then_ms: int) -> str:
    days = max(0, (now_ms - (then_ms or 0)) // 86400000)
    if days == 0:
        return "today"
    if days == 1:
        return "yesterday"
    if days < 30:
        return f"{days}d ago"
    if days < 365:
        return f"{days // 30}mo ago"
    return f"{days // 365}y ago"


def _render_knows_human(model: dict) -> str:
    """Single friendly screen: headline count, buckets, curation hints."""
    now = int(time.time() * 1000)
    lines: list[str] = []

    active = model.get("active_entities")
    if active is not None:
        headline = f"Perseus knows {active} things"
        archived = model.get("archived_entities")
        if archived:
            headline += f"  ({archived} archived — hidden)"
    else:
        n = model.get("listed", 0)
        more = "+" if model.get("truncated") else ""
        headline = f"Perseus knows {n}{more} things (newest {n} shown)"
    lines.append(headline)
    lines.append("")

    for bucket in model.get("bucket_order", _KNOWS_BUCKET_ORDER):
        items = model["buckets"].get(bucket, [])
        if not items:
            continue
        lines.append(f"## {bucket} ({len(items)})")
        for item in items[:_KNOWS_ITEMS_PER_BUCKET]:
            mark = "✔" if item["verified"] else "~"
            age = _knows_age(now, item.get("created_at_unix_ms") or 0)
            label = item["summary"] or item["key"] or item["category"]
            lines.append(
                f"  {mark} [{item['short_id']}] {label}"
                f"  ({item['category'] or 'uncategorized'}, {age})"
            )
        if len(items) > _KNOWS_ITEMS_PER_BUCKET:
            lines.append(f"  … and {len(items) - _KNOWS_ITEMS_PER_BUCKET} more")
        lines.append("")

    if model.get("older_conversational"):
        lines.append(
            f"…plus {model['older_conversational']} older conversation/session "
            "memories (auto-captured; not shown)"
        )
        lines.append("")

    lines.append("✔ = verified   ~ = unverified")
    lines.append(
        "Curate: perseus knows --show <id> · --correct <id> \"the right value\" "
        "· --forget <id>"
    )
    return "\n".join(lines)


def _render_knows_json(model: dict) -> str:
    return json.dumps(model, indent=2, default=str)


def _knows_describe(hit) -> str:
    """Plain-language one-liner used by confirm prompts and --show."""
    text = (hit.summary or hit.content or "").strip().replace("\n", " ")
    if len(text) > 160:
        text = text[:157] + "…"
    where = f"{hit.category}/{hit.key}" if hit.category or hit.key else hit.id
    return f"[{_knows_short_id(hit.id)}] {where}: {text}"


def _knows_confirm(prompt: str, assume_yes: bool) -> bool:
    if assume_yes:
        return True
    try:
        answer = input(f"{prompt} [y/N] ")
    except EOFError:
        return False
    return answer.strip().lower() in ("y", "yes")


def cmd_knows(args, cfg) -> int:
    """`perseus knows` — show and curate what the Vault holds (#692)."""
    knows_cfg = cfg.get("knows") or {}
    if not knows_cfg.get("enabled", True):
        print("perseus knows is disabled (config: knows.enabled = false)")
        return 1

    connector = VaultConnector(cfg)
    try:
        limit = int(getattr(args, "limit", None) or
                    knows_cfg.get("limit", _KNOWS_DEFAULT_LIMIT))
        include_archived = bool(getattr(args, "include_archived", False))
        hits, err = connector.browse(limit=limit, include_archived=include_archived)
        if err:
            print("Perseus Vault is unreachable — nothing to show.")
            print(f"  reason: {err}")
            print("  Run `perseus doctor` to diagnose the memory bridge.")
            return 1

        show_id = getattr(args, "show", None)
        forget_id = getattr(args, "forget", None)
        correct_id = getattr(args, "correct", None)

        if show_id:
            hit, rerr = _knows_resolve_id(hits, show_id)
            if hit is None:
                print(f"error: {rerr}")
                return 1
            full = connector.get_entity(hit.id) or {}
            detail = {**_knows_item(hit), "body_json": full.get("body_json", "")}
            for extra in ("source", "status", "links", "tags", "topic_path"):
                if extra in full:
                    detail[extra] = full[extra]
            print(json.dumps(detail, indent=2, default=str))
            return 0

        if forget_id:
            hit, rerr = _knows_resolve_id(hits, forget_id)
            if hit is None:
                print(f"error: {rerr}")
                return 1
            if not hit.category or not hit.key:
                print(f"error: [{_knows_short_id(hit.id)}] has no (category, key) "
                      "address — cannot forget via the Vault tool")
                return 1
            print(f"About to forget (reversible archive):\n  {_knows_describe(hit)}")
            if not _knows_confirm("Forget this memory?", getattr(args, "yes", False)):
                print("cancelled")
                return 1
            ok, ferr = connector.forget(hit.category, hit.key,
                                        reason="user request via `perseus knows --forget`")
            if not ok:
                print(f"error: forget failed: {ferr}")
                return 1
            print(f"forgotten (archived): [{_knows_short_id(hit.id)}] — "
                  "reversible; it is hidden, not deleted")
            return 0

        if correct_id:
            correction = getattr(args, "value", None) or ""
            if not correction.strip():
                print("error: --correct needs the corrected value: "
                      'perseus knows --correct <id> "the right value"')
                return 1
            hit, rerr = _knows_resolve_id(hits, correct_id)
            if hit is None:
                print(f"error: {rerr}")
                return 1
            old = (hit.content or hit.summary or "").strip()
            print(f"About to correct:\n  {_knows_describe(hit)}\n  → {correction}")
            if not _knows_confirm("Record this correction?", getattr(args, "yes", False)):
                print("cancelled")
                return 1
            ok, cerr = connector.correct(
                wrong_approach=old,
                user_correction=correction,
                task_context=f"user correction via `perseus knows` for {hit.category}/{hit.key}",
                category=hit.category,
            )
            if not ok:
                print(f"error: correct failed: {cerr}")
                return 1
            print(f"corrected: [{_knows_short_id(hit.id)}] — the wrong→right pair "
                  "is recorded; the old value is superseded, not erased")
            return 0

        model = _knows_model(hits, connector.stats(), limit)
        if getattr(args, "json", False):
            print(_render_knows_json(model))
        else:
            print(_render_knows_human(model))
        return 0
    finally:
        try:
            connector.close()
        except Exception:
            pass
# ──────────────────────────────── @speculate ─────────────────────────────────
#
# #607 — speculative context prefetch via next-intent prediction.
#
# Perseus's `prefetch` is reactive: it warms what the *current* template
# references. This module is anticipatory: it predicts the user's likely NEXT
# task from recorded waypoint/checkpoint transitions and pre-warms the cache
# entries that task's context will need, so the first render of the next turn
# is already hot — speculative execution for context assembly.
#
# Design contract (issue #607):
#   * Transparent predictor — an order-1 Markov / frequency model over the
#     checkpoint (waypoint) task sequence. NO ML dependencies. Deterministic
#     under a fixed corpus (no wall-clock inputs in prediction).
#   * `@speculate k=N budget=<tokens>` pragma in a source opts that source in;
#     the whole feature is additionally gated on `speculate.enabled` config
#     (DEFAULT FALSE). Disabled == zero predictions, zero cache writes, zero
#     stats writes — current behavior exactly.
#   * Speculation runs synchronously AFTER a render completes (renderer.py
#     calls run_speculation() as its last step) so it can never delay or
#     interleave with the live render.
#   * Cache safety: speculative warms are executed through the SAME
#     `_execute_prefetch_directive` used by prefetch rules, so a speculative
#     entry uses the exact key derivation the renderer reads
#     (base key = sha256("<directive> <args> :: <workspace>"), plus the
#     dependency fingerprint suffix). A speculative warm is therefore just an
#     *early* warm — never a divergent key that could shadow or poison real
#     reads. Revalidation is inherited from the cache layer itself: the
#     renderer re-derives the fingerprint on the real turn, so any dependency
#     change misses the speculative entry, and TTL expiry bounds staleness.
#     A wrong prediction costs nothing on the real turn.
#   * Confidence gating: only predictions with probability >=
#     `speculate.confidence_threshold` are warmed.
#   * Budget: cumulative estimated tokens of newly-warmed values are bounded
#     by `budget` (pragma) / `speculate.budget_tokens` (config). Once the
#     budget is spent, remaining candidates are skipped.
#   * Observability: `perseus explain --speculate` shows predicted next
#     intents + probabilities, the historical hit/miss rate of past
#     speculation, and current cache warmth per candidate.
#
# Pluggable predictor interface (for a future LLM backend):
#   A predictor is any object with:
#       fit(sequence: list[str]) -> None
#           Train on the chronological intent sequence.
#       predict(current: str | None, k: int) -> list[tuple[str, float]]
#           Top-k (intent, probability) for the next intent, probabilities
#           sorted descending with a deterministic tie-break.
#   Register new backends in `_speculate_build_predictor`. Unknown backend
#   names fall back to the transparent Markov predictor.
#
# Stats file (input for a future @bandit ledger integration — this module
# deliberately does NOT write to the bandit ledger itself; a follow-up wires
# these outcomes in). One JSON file per workspace under the render cache dir:
#
#   <cache_dir>/speculate_stats-<workspace_hash16>.json
#   {
#     "version": 1,
#     "workspace": "<abs workspace path or ''>",
#     "hits": <int>,          # settled predictions whose top-1 matched
#     "misses": <int>,        # settled predictions whose top-1 did not match
#     "pending": {            # last unsettled prediction (or null)
#       "basis_intent": "<intent the prediction was made from>",
#       "basis_marker": "<latest checkpoint filename at prediction time>",
#       "predicted": [{"intent": "...", "probability": 0.0}, ...]
#     },
#     "outcomes": [           # bounded FIFO (speculate.max_records)
#       {"predicted_top1": "...", "actual": "...", "hit": true,
#        "probability": 0.0, "basis_marker": "...", "settled_marker": "..."}
#     ],
#     "last_run": {           # summary of the most recent speculation pass
#       "k": 3, "budget_tokens": 2000, "spent_tokens": 0,
#       "budget_exhausted": false,
#       "predicted": [...], "warmed": 0, "skipped": 0, "failed": 0
#     }
#   }
#
# Writes are atomic (temp file + os.replace) so a crash mid-write can never
# corrupt the stats file.

_SPECULATE_DEFAULTS = {
    "enabled": False,
    "k": 3,
    "budget_tokens": 2000,
    "confidence_threshold": 0.30,
    "history_window": 200,
    "backend": "markov",
    "intents": {},
    "max_records": 200,
}

_SPECULATE_PRAGMA_RE = re.compile(r'^\s*@speculate\b(.*)$', re.IGNORECASE)


def _speculate_config(cfg: dict) -> dict:
    """Normalize the `speculate:` config block against defaults."""
    raw = cfg.get("speculate", {})
    if isinstance(raw, bool):
        raw = {"enabled": raw}
    if not isinstance(raw, dict):
        raw = {}
    out = dict(_SPECULATE_DEFAULTS)
    out.update(raw)
    out["enabled"] = str(out.get("enabled", False)).strip().lower() in {"true", "1", "yes", "on"}
    out["backend"] = str(out.get("backend") or "markov").strip().lower()
    for key, default in (("k", 3), ("budget_tokens", 2000),
                         ("history_window", 200), ("max_records", 200)):
        try:
            out[key] = max(0, int(out.get(key, default)))
        except (TypeError, ValueError):
            out[key] = default
    try:
        out["confidence_threshold"] = float(out.get("confidence_threshold", 0.30))
    except (TypeError, ValueError):
        out["confidence_threshold"] = 0.30
    if not isinstance(out.get("intents"), dict):
        out["intents"] = {}
    return out


# ───────────────────────── Next-intent predictor ─────────────────────────────

class MarkovIntentPredictor:
    """Order-1 Markov / frequency next-intent predictor.

    Transparent and dependency-free: transition counts over the recorded
    intent sequence, falling back to global frequency when the current
    intent has no recorded outgoing transitions. Deterministic — ties are
    broken by intent name, and nothing here reads the clock.

    Implements the pluggable predictor interface documented in the module
    header (fit / predict), so an LLM-backed predictor can be swapped in
    behind `_speculate_build_predictor` later without touching callers.
    """

    backend_name = "markov"

    def __init__(self) -> None:
        self._transitions: dict[str, dict[str, int]] = {}
        self._frequency: dict[str, int] = {}

    def fit(self, sequence: list[str]) -> None:
        self._transitions = {}
        self._frequency = {}
        for intent in sequence:
            self._frequency[intent] = self._frequency.get(intent, 0) + 1
        for prev, nxt in zip(sequence, sequence[1:]):
            row = self._transitions.setdefault(prev, {})
            row[nxt] = row.get(nxt, 0) + 1

    def predict(self, current: "str | None", k: int = 3) -> list[tuple[str, float]]:
        counts = None
        if current is not None:
            counts = self._transitions.get(current)
        if not counts:
            counts = self._frequency
        total = sum(counts.values())
        if not total or k <= 0:
            return []
        ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
        return [(intent, count / total) for intent, count in ranked[:k]]


def most_recent_baseline(sequence: list[str]) -> "str | None":
    """Naive baseline for #607 acceptance: predict the most recent task again."""
    return sequence[-1] if sequence else None


def _speculate_build_predictor(scfg: dict):
    """Backend factory — the pluggable seam for future predictor backends.

    "markov" (default) is the only shipped backend. Unknown names fall back
    to Markov rather than failing, so a config typo cannot disable renders.
    """
    return MarkovIntentPredictor()


# ───────────────────────── Intent history (waypoints) ────────────────────────

def _speculate_intent_history(cfg: dict, workspace: "Path | None" = None,
                              window: int = 200,
                              files: "list | None" = None) -> list[str]:
    """Chronological task-intent sequence from the checkpoint (waypoint) store.

    Checkpoints ARE the waypoint transitions: each `perseus checkpoint
    --task X` appends an intent. When a workspace is given, checkpoints
    tagged with a different workspace are excluded (untagged ones are kept).
    Ordering comes from the checkpoint filename sort (deterministic under a
    fixed corpus — no wall-clock reads here).

    #636: bounded work. Every opted-in render used to read + yaml-parse EVERY
    checkpoint file and apply the `window` slice only afterwards — O(store
    size) per render (~+155 ms at 200 files, ~+287 ms at 1000). Now the
    newest-first listing is walked with an early stop once `window` matching
    intents are collected. The newest `window` matching intents, reversed,
    ARE the old `seq[-window:]` — identical output for every store, mixed
    workspaces included — but parsing stops as soon as the window is full
    instead of always visiting every file. With `window <= 0` (unbounded)
    behavior is unchanged. `files` lets callers reuse one
    `_list_checkpoint_files` listing across history + marker instead of
    re-listing the store.
    """
    ws_resolved = None
    if workspace is not None:
        try:
            ws_resolved = str(Path(workspace).expanduser().resolve())
        except (OSError, ValueError):
            ws_resolved = str(workspace)
    if files is None:
        files = _list_checkpoint_files(cfg)
    newest_first: list[str] = []
    for fp in files:  # newest-first (reverse chronological)
        if window > 0 and len(newest_first) >= window:
            break  # enough intents collected — skip the older tail entirely
        cp = _load_checkpoint_file(fp)
        if not cp:
            continue
        if ws_resolved and cp.get("workspace"):
            try:
                cp_ws = str(Path(str(cp["workspace"])).expanduser().resolve())
            except (OSError, ValueError):
                cp_ws = str(cp["workspace"])
            if cp_ws != ws_resolved:
                continue
        task = str(cp.get("task") or "").strip()
        if task:
            newest_first.append(task)
    newest_first.reverse()  # ascending chronological, like the old seq[-window:]
    return newest_first


def _speculate_latest_marker(cfg: dict, files: "list | None" = None) -> str:
    """Identity of the newest checkpoint — used to detect that a real turn
    happened between two speculation passes (settlement trigger).

    #636: accepts a pre-computed `_list_checkpoint_files` listing so callers
    that already listed the store don't pay a second directory scan."""
    if files is None:
        files = _list_checkpoint_files(cfg)
    return files[0].name if files else ""


# ───────────────────────────── Stats persistence ─────────────────────────────

def _default_speculate_stats(workspace: "Path | None") -> dict:
    return {
        "version": 1,
        "workspace": str(workspace) if workspace else "",
        "hits": 0,
        "misses": 0,
        "pending": None,
        "outcomes": [],
        "last_run": None,
    }


def _speculate_stats_path(cfg: dict, workspace: "Path | None") -> Path:
    ws_key = _workspace_hash(Path(workspace)) if workspace else "global"
    return _safe_cache_dir(cfg) / f"speculate_stats-{ws_key}.json"


def _load_speculate_stats(cfg: dict, workspace: "Path | None") -> dict:
    path = _speculate_stats_path(cfg, workspace)
    stats = _default_speculate_stats(workspace)
    try:
        loaded = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(loaded, dict):
            stats.update(loaded)
    except (OSError, ValueError):
        pass
    for key, default in (("hits", 0), ("misses", 0)):
        try:
            stats[key] = max(0, int(stats.get(key, default)))
        except (TypeError, ValueError):
            stats[key] = default
    if not isinstance(stats.get("outcomes"), list):
        stats["outcomes"] = []
    return stats


def _save_speculate_stats(cfg: dict, workspace: "Path | None", stats: dict) -> None:
    """Atomic write: temp file in the same directory + os.replace."""
    path = _speculate_stats_path(cfg, workspace)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        import tempfile as _tempfile
        tmp_fd, tmp_path = _tempfile.mkstemp(dir=str(path.parent), suffix=".json")
        try:
            with os.fdopen(tmp_fd, "w", encoding="utf-8") as fh:
                json.dump(stats, fh, indent=2, default=str)
            os.replace(tmp_path, path)
        except Exception:
            Path(tmp_path).unlink(missing_ok=True)
            raise
    except Exception as exc:
        # Stats are advisory — never let bookkeeping break speculation/render.
        sys.stderr.write(f"perseus speculate: could not persist stats: {exc}\n")


# ─────────────────────────── @speculate pragma parse ─────────────────────────

def _extract_speculate_pragmas(body_lines: list[str]) -> "tuple[list[str], dict | None]":
    """Strip `@speculate [k=N] [budget=M]` pragma lines from a source body.

    Fence-aware (an @speculate inside a fenced code block is content and is
    preserved). Returns (remaining_lines, params) where params is None when
    no pragma was present, else {"k": int|None, "budget": int|None} from the
    FIRST pragma. The pragma is engine configuration, not content — it never
    reaches rendered output, whether or not speculation is enabled.
    """
    out_lines: list[str] = []
    params: "dict | None" = None
    fence = _new_fence_state()
    for line in body_lines:
        if _fence_step(fence, line):
            out_lines.append(line)
            continue
        m = _SPECULATE_PRAGMA_RE.match(line)
        if not m:
            out_lines.append(line)
            continue
        if params is None:
            params = {"k": None, "budget": None}
            rest = m.group(1) or ""
            mk = re.search(r'\bk=(\d+)\b', rest)
            if mk:
                params["k"] = int(mk.group(1))
            mb = re.search(r'\bbudget=(\d+)\b', rest)
            if mb:
                params["budget"] = int(mb.group(1))
        # pragma line dropped from output either way
    return out_lines, params


# ───────────────────────────── Candidate contexts ────────────────────────────

def _speculate_candidates_for_intent(intent: str, scfg: dict) -> list:
    """Prefetch directive items configured for a predicted intent.

    `speculate.intents` maps an fnmatch pattern over intent names to a
    directive line (or list of lines) in the same shape prefetch rules use,
    e.g. {"deploy*": ['@read "runbook.md" @cache ttl=300']}. Patterns are
    walked in sorted order for determinism.
    """
    intents = scfg.get("intents") or {}
    items: list = []
    for pattern in sorted(intents.keys(), key=str):
        if _pattern_matches(intent, pattern):
            value = intents[pattern]
            if isinstance(value, (str, dict)):
                value = [value]
            if isinstance(value, list):
                items.extend(value)
    return items


def _speculate_skip_entry(item: object, intent: str, probability: float, reason: str) -> dict:
    """A skipped speculation entry (shape mirrors prefetch result entries)."""
    directive, _raw_args, raw, _err = _prefetch_directive_from_config(item) if item else (None, "", "", None)
    return {
        "rule": f"speculate:{intent}",
        "trigger": "speculate",
        "trigger_directive": "@speculate",
        "directive": directive,
        "line": raw,
        "status": "skipped",
        "reason": reason,
        "cache": {"mode": "", "ttl": None, "key": None},
        "intent": intent,
        "probability": round(float(probability), 4),
        "est_tokens": 0,
    }


def _speculate_probe(item: object, cfg: dict, workspace: "Path | None") -> "dict | None":
    """Current cache warmth for a candidate directive, without executing it.

    MUST mirror the key derivation of `_execute_prefetch_directive`
    (query.py): base key over "<directive> <clean_args> :: <workspace>",
    plus the dependency fingerprint unless the item opted out with
    `@cache nofingerprint`. Key parity with the real render read path is
    pinned by test_speculate.py::test_speculative_warm_is_read_by_real_render.
    """
    directive, raw_args, raw, parse_error = _prefetch_directive_from_config(item)
    if parse_error or not directive:
        return None
    clean_args, cache_mode, cache_ttl, _mock = _parse_cache_modifier(raw_args)
    _ws = str(workspace.resolve()) if workspace else ""
    base_key = _cache_key(f"{directive} {clean_args} :: {_ws}")
    fp = ""
    if cache_mode != "nofingerprint":
        fp = _dependency_fingerprint(directive, clean_args, workspace, cfg)
    key = f"{base_key}.{fp}" if fp else base_key
    warm = cache_get(key, cache_mode, cache_ttl, cfg) is not None
    return {"line": raw, "cache_key": key, "cache_mode": cache_mode, "warm": warm}


# ───────────────────────────── Speculation engine ────────────────────────────

def run_speculation(cfg: dict, workspace: "Path | None" = None,
                    k: "int | None" = None,
                    budget_tokens: "int | None" = None) -> dict:
    """Predict the next intents and warm their contexts within budget.

    Called synchronously after a render completes (renderer.py) and from
    `prefetch_source` (query.py). When `speculate.enabled` is false this
    returns immediately: no prediction, no cache writes, no stats writes.
    """
    scfg = _speculate_config(cfg)
    effective_k = int(k) if k is not None else scfg["k"]
    effective_budget = int(budget_tokens) if budget_tokens is not None else scfg["budget_tokens"]
    out = {
        "enabled": scfg["enabled"],
        "backend": scfg["backend"],
        "k": effective_k,
        "budget_tokens": effective_budget,
        "confidence_threshold": scfg["confidence_threshold"],
        "current_intent": None,
        "predicted": [],
        "results": [],
        "summary": {"warmed": 0, "skipped": 0, "failed": 0,
                    "spent_tokens": 0, "budget_exhausted": False},
    }
    if not scfg["enabled"]:
        return out

    # #636: one store listing shared by history + marker (was two scans).
    cp_files = _list_checkpoint_files(cfg)
    history = _speculate_intent_history(cfg, workspace, scfg["history_window"],
                                        files=cp_files)
    current = history[-1] if history else None
    out["current_intent"] = current
    marker = _speculate_latest_marker(cfg, files=cp_files)

    stats = _load_speculate_stats(cfg, workspace)

    # ── Settle the previous prediction (hit/miss accounting) ──
    # A prediction is settled when a NEW checkpoint has appeared since it was
    # made: the newest task is then the "actual" next intent.
    pending = stats.get("pending")
    if isinstance(pending, dict) and pending.get("basis_marker") != marker:
        predicted_prev = pending.get("predicted") or []
        top1 = predicted_prev[0].get("intent") if predicted_prev else None
        hit = bool(top1 is not None and current is not None and top1 == current)
        if hit:
            stats["hits"] += 1
        else:
            stats["misses"] += 1
        stats["outcomes"].append({
            "predicted_top1": top1,
            "actual": current,
            "hit": hit,
            "probability": (predicted_prev[0].get("probability", 0.0)
                            if predicted_prev else 0.0),
            "basis_marker": str(pending.get("basis_marker", "")),
            "settled_marker": marker,
        })
        max_records = scfg["max_records"] or 200
        del stats["outcomes"][:-max_records]
        stats["pending"] = None

    # ── Predict ──
    predictor = _speculate_build_predictor(scfg)
    predictor.fit(history)
    predictions = predictor.predict(current, effective_k)
    out["predicted"] = [
        {"intent": intent, "probability": round(prob, 4)}
        for intent, prob in predictions
    ]
    if predictions:
        stats["pending"] = {
            "basis_intent": current,
            "basis_marker": marker,
            "predicted": out["predicted"],
        }

    # ── Warm, confidence-gated and budget-bounded ──
    threshold = scfg["confidence_threshold"]
    trigger_node = {"id": "speculate", "directive": "@speculate"}
    spent = 0
    for intent, prob in predictions:
        items = _speculate_candidates_for_intent(intent, scfg)
        if not items:
            out["results"].append(_speculate_skip_entry(
                None, intent, prob, "no speculate.intents candidate configured"))
            continue
        for item in items:
            if prob < threshold:
                out["results"].append(_speculate_skip_entry(
                    item, intent, prob,
                    f"confidence {prob:.2f} < threshold {threshold:.2f}"))
                continue
            if spent >= effective_budget:
                out["summary"]["budget_exhausted"] = True
                out["results"].append(_speculate_skip_entry(
                    item, intent, prob,
                    f"speculate budget exhausted ({spent}/{effective_budget} tokens)"))
                continue
            entry = _execute_prefetch_directive(
                item, f"speculate:{intent}", trigger_node, cfg, workspace)
            entry["intent"] = intent
            entry["probability"] = round(prob, 4)
            entry["est_tokens"] = 0
            if entry.get("status") == "ran":
                cache_info = entry.get("cache") or {}
                value = cache_get(cache_info.get("key") or "",
                                  cache_info.get("mode") or "",
                                  cache_info.get("ttl"), cfg)
                est = estimate_tokens(value) if value else 0
                entry["est_tokens"] = est
                spent += est
            out["results"].append(entry)

    out["summary"]["spent_tokens"] = spent
    out["summary"]["warmed"] = sum(1 for e in out["results"] if e.get("status") == "ran")
    out["summary"]["skipped"] = sum(1 for e in out["results"] if e.get("status") == "skipped")
    out["summary"]["failed"] = sum(1 for e in out["results"] if e.get("status") == "failed")

    stats["last_run"] = {
        "k": effective_k,
        "budget_tokens": effective_budget,
        "spent_tokens": spent,
        "budget_exhausted": out["summary"]["budget_exhausted"],
        "predicted": out["predicted"],
        "warmed": out["summary"]["warmed"],
        "skipped": out["summary"]["skipped"],
        "failed": out["summary"]["failed"],
    }
    _save_speculate_stats(cfg, workspace, stats)
    return out


def speculate_source(source_text: str, cfg: dict,
                     workspace: "Path | None" = None) -> dict:
    """Speculation entry point for a Perseus source (used by prefetch_source).

    Honours the source's `@speculate k=N budget=M` pragma when present;
    otherwise runs with the `speculate:` config defaults. Gated on
    `speculate.enabled` inside run_speculation.
    """
    _lines, params = _extract_speculate_pragmas(source_text.splitlines())
    k = params.get("k") if params else None
    budget = params.get("budget") if params else None
    return run_speculation(cfg, workspace, k=k, budget_tokens=budget)


# ─────────────────────────── explain --speculate ─────────────────────────────

def explain_speculate(cfg: dict, workspace: "Path | None" = None,
                      k: "int | None" = None) -> dict:
    """Observability payload: predicted next intents + probabilities, past
    speculation hit/miss rate, and current cache warmth per candidate.

    Read-only: never executes directives, never writes cache or stats.
    """
    scfg = _speculate_config(cfg)
    history = _speculate_intent_history(cfg, workspace, scfg["history_window"])
    current = history[-1] if history else None
    predictor = _speculate_build_predictor(scfg)
    predictor.fit(history)
    effective_k = int(k) if k is not None else scfg["k"]
    predictions = predictor.predict(current, effective_k)

    predicted = []
    for intent, prob in predictions:
        candidates = []
        for item in _speculate_candidates_for_intent(intent, scfg):
            probe = _speculate_probe(item, cfg, workspace)
            if probe:
                candidates.append(probe)
        predicted.append({
            "intent": intent,
            "probability": round(prob, 4),
            "meets_threshold": prob >= scfg["confidence_threshold"],
            "candidates": candidates,
        })

    stats = _load_speculate_stats(cfg, workspace)
    settled = stats["hits"] + stats["misses"]
    return {
        "enabled": scfg["enabled"],
        "backend": scfg["backend"],
        "k": effective_k,
        "confidence_threshold": scfg["confidence_threshold"],
        "history_length": len(history),
        "current_intent": current,
        "baseline_most_recent": most_recent_baseline(history),
        "predicted": predicted,
        "stats": {
            "hits": stats["hits"],
            "misses": stats["misses"],
            "settled": settled,
            "hit_rate": round(stats["hits"] / settled, 4) if settled else None,
        },
        "stats_path": str(_speculate_stats_path(cfg, workspace)),
    }


def format_explain_speculate_human(data: dict) -> str:
    """Human-readable rendering of the explain_speculate payload."""
    lines = [
        (f"Speculate: enabled={str(data['enabled']).lower()} "
         f"backend={data['backend']} k={data['k']} "
         f"threshold={data['confidence_threshold']:.2f}"),
        f"History: {data['history_length']} intent(s); current: "
        f"{data['current_intent'] or '(none)'}",
        f"Baseline (most-recent): {data['baseline_most_recent'] or '(none)'}",
    ]
    if not data["predicted"]:
        lines.append("Predicted next intents: (none — no recorded transitions)")
    else:
        lines.append("Predicted next intents:")
        for idx, p in enumerate(data["predicted"], start=1):
            gate = "" if p["meets_threshold"] else " (below threshold)"
            warm = sum(1 for c in p["candidates"] if c.get("warm"))
            lines.append(
                f"  {idx}. {p['intent']}  p={p['probability']:.2f}{gate}  "
                f"[{len(p['candidates'])} candidate(s), {warm} warm]"
            )
            for cand in p["candidates"]:
                state = "warm" if cand.get("warm") else "cold"
                lines.append(f"     - {state}: {cand['line']}")
    st = data["stats"]
    rate = f"{st['hit_rate']:.2f}" if st["hit_rate"] is not None else "n/a"
    lines.append(
        f"Past speculation: hits={st['hits']} misses={st['misses']} "
        f"hit_rate={rate} (settled={st['settled']})"
    )
    lines.append(f"Stats file: {data['stats_path']}")
    return "\n".join(lines)


def cmd_explain(args, cfg) -> int:
    """`perseus explain --speculate` — speculation observability (#607)."""
    if not getattr(args, "speculate", False):
        print(
            "perseus explain: pass --speculate for next-intent speculation "
            "observability (for the per-render directive manifest, use "
            "`perseus render --explain`).",
            file=sys.stderr,
        )
        return 2
    ws = getattr(args, "workspace", None)
    workspace = Path(ws).expanduser().resolve() if ws else Path.cwd()
    cfg = load_config(workspace)
    k = None
    src = getattr(args, "source", None)
    if src:
        src_path = Path(src).expanduser().resolve()
        if src_path.exists():
            try:
                _lines, params = _extract_speculate_pragmas(
                    src_path.read_text(errors="replace", encoding="utf-8").splitlines()
                )
                if params and params.get("k"):
                    k = params["k"]
            except OSError:
                pass
    data = explain_speculate(cfg, workspace, k=k)
    if getattr(args, "json", False):
        print(json.dumps(data, indent=2, default=str))
    else:
        print(format_explain_speculate_human(data))
    return 0
# ──────────────────────────────── Render ──────────────────────────────────────

# Phase 24 — internal imports (stripped by build; defined earlier in concatenated artifact)


def _atomic_write_text(out_path: Path, text: str) -> None:
    """Write ``text`` to ``out_path`` atomically (tempfile + os.replace).

    #646: rendered outputs (AGENTS.md, .hermes.md) are rewritten by
    `perseus watch` while an agent may be mid-read, and a hard stop can land
    mid-write — especially on Windows, where SIGTERM handlers never fire
    (task kill = TerminateProcess), so any non-Ctrl-C stop of `watch` can
    truncate the file. A torn context file silently degrades every agent
    that reads it. Writing to a tempfile in the SAME directory and
    os.replace()-ing guarantees readers see either the old or the new file,
    never a partial one — mirroring the render cache's cache_set pattern.
    """
    import tempfile
    import stat as _stat
    # #672: a non-regular output target (e.g. `/dev/null`, a FIFO, or a device
    # node) can't go through the sibling-tempfile + os.replace scheme. The temp
    # file is created in the target's parent dir (`/dev/` for `/dev/null`),
    # where we may lack write permission, so the atomic write raises
    # PermissionError before it ever reaches os.replace. Atomicity is
    # meaningless for a sink like /dev/null anyway, so write through directly.
    try:
        target_mode = out_path.stat().st_mode
    except OSError:
        target_mode = None  # doesn't exist yet — the normal atomic-write case
    if target_mode is not None and not _stat.S_ISREG(target_mode):
        with out_path.open("w", encoding="utf-8") as fh:
            fh.write(text)
        return
    tmp_name = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", prefix=out_path.name + ".", suffix=".tmp",
            dir=str(out_path.parent), delete=False, encoding="utf-8",
        ) as tmp:
            tmp_name = tmp.name
            tmp.write(text)
        os.replace(tmp_name, out_path)
    except BaseException:
        # Never leave a stray tempfile beside the output on failure.
        if tmp_name is not None:
            try:
                os.unlink(tmp_name)
            except OSError:
                pass
        raise


def _render_run_failed(source, reason: str) -> None:
    """Emit a structured, stamped per-run failure marker to stderr (#799).

    A scheduled render agent routes stderr to a long-lived log that accumulates
    historical warnings; a stamped ``render FAILED`` line with an explicit
    reason lets an operator grep the *current* run's outcome instead of guessing
    from a pile of old noise. Mirrors the success path, which already prints its
    own stamped ``rendered ...`` line — both share the ``perseus <v>: render``
    prefix, so one grep shows every run's status."""
    ts = datetime.now().astimezone().isoformat(timespec="seconds")
    sys.stderr.write(
        f"perseus {_PERSEUS_VERSION}: render FAILED source={source} — {reason} at {ts}\n")


def cmd_render(args, cfg):
    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        is_default_path = source_path == Path("~/.perseus/context.md").expanduser().resolve() or \
                          source_path == Path(".perseus/context.md").resolve()
        if is_default_path:
            print(f"Error: context file not found: {source_path}. Run `perseus init` to create it.", file=sys.stderr)
        else:
            print(f"Error: file not found: {source_path}", file=sys.stderr)
        _render_run_failed(source_path, "source not found")
        sys.exit(1)

    workspace = _infer_workspace(source_path)
    cfg = load_config(workspace)
    _merge_pack_vault_config(cfg, workspace)  # #441: per-workspace vault overrides

    text = source_path.read_text(errors="replace", encoding="utf-8")
    fmt = getattr(args, "format", "md")
    title = source_path.stem.replace("-", " ").replace("_", " ").title()

    # Determine tier: CLI --tier > config default > fallback to 3
    max_tier = getattr(args, "tier", None)
    if max_tier is None:
        max_tier = cfg.get("render", {}).get("default_tier", 3)
    if max_tier is None:
        max_tier = 3

    no_cache = getattr(args, "no_cache", False)

    # --explain: emit directive execution manifest instead of rendered output
    if getattr(args, "explain", False):
        import json as _json
        _stats: dict = {"directive_count": 0, "cache_hits": 0, "cache_misses": 0}
        _directives = []
        _skipped = []
        rendered = render_source(text, cfg, workspace, max_tier=max_tier,
                                 _directive_collector=_directives,
                                 _stats=_stats,
                                 _skipped_directives=_skipped,
                                 no_cache=no_cache)
        manifest = {
            "source": str(source_path),
            "workspace": str(workspace),
            "version": _PERSEUS_VERSION,
            # #605: stable id for outcome feedback — `perseus feedback <render_id> ...`
            "render_id": _bandit_render_id(text, workspace),
            "tier": max_tier,
            "summary": {
                "directive_count": _stats["directive_count"],
                "cache_hits": _stats["cache_hits"],
                "cache_misses": _stats["cache_misses"],
                "skipped": len(_skipped),
            },
            "directives": _directives,
            "skipped": _skipped,
        }
        print(_json.dumps(manifest, indent=2, default=str))
        return

    rendered = render_output(text, fmt, cfg, workspace, title=title, max_tier=max_tier, no_cache=no_cache)

    is_assistant_format = fmt in ("agents-md", "claude-md", "cursorrules", "copilot-instructions")
    output = getattr(args, "output", None)
    # Phase 24: auto-resolve default output path for assistant formats
    if is_assistant_format and not output:
        output = get_default_output_path(fmt, str(workspace))

    strict = getattr(args, "strict", False)
    if strict and "⚠" in rendered:
        n_warn = rendered.count("⚠")
        print(f"Perseus: strict mode — {n_warn} warning(s) in rendered output", file=sys.stderr)
        _render_run_failed(source_path, f"strict mode: {n_warn} warning(s) in rendered output")
        sys.exit(1)

    if output:
        out_path = Path(output)
        out_path.parent.mkdir(parents=True, exist_ok=True)
        # Preserve existing file ownership if output already exists (#228)
        # #646: both branches write atomically — see _atomic_write_text.
        if out_path.exists():
            st = out_path.stat()
            _atomic_write_text(out_path, rendered)
            # Preserve ownership where the platform supports it. os.chown is
            # absent on Windows — calling it would raise AttributeError (not
            # OSError) and crash the render; st_uid/st_gid are meaningless there.
            if hasattr(os, "chown"):
                try:
                    os.chown(out_path, st.st_uid, st.st_gid)
                except OSError:
                    pass  # chown may fail in containers without CAP_CHOWN
            # Also restore the mode: NamedTemporaryFile creates 0600 on POSIX
            # and os.replace carries that onto the output — a previously
            # world-readable AGENTS.md must not become owner-only.
            try:
                os.chmod(out_path, st.st_mode & 0o7777)
            except OSError:
                pass
        else:
            _atomic_write_text(out_path, rendered)

        # Versioned, timestamped audit line on every render-to-file (#431).
        # Scheduled jobs route stdout to a log (e.g. perseus-render.out.log),
        # so this makes the last successful render — and which Perseus version
        # produced it — auditable, surfacing silent staleness. Suppress with
        # --quiet for scripted callers that parse stdout.
        if not getattr(args, "quiet", False):
            warn_count = rendered.count("⚠")
            warn_note = f", {warn_count} warning(s)" if warn_count else ""
            ts = datetime.now().astimezone().isoformat(timespec="seconds")
            print(
                f"perseus {_PERSEUS_VERSION}: rendered {source_path} → {out_path} "
                f"({len(rendered.encode('utf-8', errors='replace')):,} bytes{warn_note}) at {ts}"
            )
    else:
        print(rendered)


def cmd_scan(args, cfg):
    """Scan a context's *rendered* output for secrets (and optionally PII).

    A build-time gate: render the source with redaction turned OFF (in-memory
    only — nothing is written to disk), then run the detectors against the raw
    resolved text so leaks pulled in via @env/@query/@include/@tool are caught.
    Prints a report and exits non-zero when findings exist, so CI can block a
    context that would leak credentials or PII. Use --report-only to always
    exit 0 (report without failing).
    """
    import copy as _copy
    import json as _json

    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        print(f"Error: file not found: {source_path}", file=sys.stderr)
        sys.exit(1)

    workspace = _infer_workspace(source_path)
    cfg = load_config(workspace)
    _merge_pack_vault_config(cfg, workspace)
    text = source_path.read_text(errors="replace", encoding="utf-8")

    max_tier = getattr(args, "tier", None)
    if max_tier is None:
        max_tier = cfg.get("render", {}).get("default_tier", 3) or 3

    # Render with redaction disabled so the scanner sees raw resolved content.
    scan_cfg = _copy.deepcopy(cfg)
    scan_cfg.setdefault("redaction", {})["enabled"] = False
    rendered = render_source(text, scan_cfg, workspace, max_tier=max_tier,
                             no_cache=getattr(args, "no_cache", False))

    # PII: --pii / --no-pii override config redaction.detect_pii.
    include_pii = None
    if getattr(args, "pii", False):
        include_pii = True
    elif getattr(args, "no_pii", False):
        include_pii = False

    report = scan_text(rendered, cfg, include_pii=include_pii)

    if getattr(args, "json", False):
        print(_json.dumps(report, indent=2, default=str))
    else:
        if report["total"] == 0:
            scope = "secrets + PII" if report.get("pii_scanned") else "secrets"
            print(f"perseus scan: clean — no {scope} detected in {source_path.name}")
        else:
            print(f"perseus scan: {report['total']} finding(s) in {source_path.name}", file=sys.stderr)
            by_rule = ", ".join(f"{n}={c}" for n, c in sorted(report["counts"].items()))
            print(f"  by detector: {by_rule}", file=sys.stderr)
            for f in report["findings"]:
                print(f"  line {f['line']}: [{f['rule']}] {f['context']}", file=sys.stderr)
            if not report.get("pii_scanned"):
                print("  (re-run with --pii to also scan for emails, SSNs, phone numbers, cards)", file=sys.stderr)

    if report["total"] > 0 and not getattr(args, "report_only", False):
        sys.exit(2)
    return 0


def cmd_compress(args, cfg):
    """Render a context, then deterministically compress it and report the
    token-reduction %.

    Structure-preserving (fenced code blocks kept verbatim) and fully
    deterministic, so the reported reduction is a citable, build-assertable
    number. Writes the compressed output to --output or stdout; the stats go to
    stderr (human) or stdout (--json).
    """
    import copy as _copy
    import json as _json

    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        print(f"Error: file not found: {source_path}", file=sys.stderr)
        sys.exit(1)

    workspace = _infer_workspace(source_path)
    cfg = load_config(workspace)
    _merge_pack_vault_config(cfg, workspace)
    text = source_path.read_text(errors="replace", encoding="utf-8")

    max_tier = getattr(args, "tier", None)
    if max_tier is None:
        max_tier = cfg.get("render", {}).get("default_tier", 3) or 3

    rendered = render_source(text, cfg, workspace, max_tier=max_tier,
                             no_cache=getattr(args, "no_cache", False))

    # Force-enable compression for this explicit invocation; let CLI flags
    # override the configured sub-options.
    ccfg = _copy.deepcopy(cfg)
    comp = ccfg.setdefault("compress", {})
    comp["enabled"] = True
    if getattr(args, "max_blank_lines", None) is not None:
        comp["max_blank_lines"] = args.max_blank_lines
    if getattr(args, "no_dedup", False):
        comp["dedup_adjacent"] = False
    if getattr(args, "strip_comments", False):
        comp["strip_comments"] = True

    compressed, report = compress_text(rendered, ccfg)

    output = getattr(args, "output", None)
    if output:
        out_path = Path(output)
        out_path.parent.mkdir(parents=True, exist_ok=True)
        out_path.write_text(compressed, encoding="utf-8")
    elif not getattr(args, "json", False):
        print(compressed)

    if getattr(args, "json", False):
        print(_json.dumps(report, indent=2))
    else:
        r = report
        rules = f"; rules: {', '.join(r['rules'])}" if r["rules"] else "; no-op"
        print(
            f"perseus compress: {r['tokens_before']} -> {r['tokens_after']} tokens "
            f"(-{r['reduction_pct']}%, ~{r['tokens_saved']} saved); "
            f"{r['bytes_before']} -> {r['bytes_after']} bytes{rules}",
            file=sys.stderr,
        )
    return 0


def cmd_preview(args, cfg):
    """Render a context, then show a deterministic, diffable token budget — where
    the tokens go, per directive and per markdown section.

    Pairs with ``perseus compress``: compress shrinks the context, preview shows
    what is taking up the space to begin with. Output is intentionally **stable
    and free of volatile fields** (no timestamps, durations, or cache flags), so
    the same source yields byte-identical output and a build can diff its context
    budget over time. ``--json`` emits a stable schema for CI diffing.
    """
    import json as _json
    import re as _re

    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        print(f"Error: file not found: {source_path}", file=sys.stderr)
        sys.exit(1)

    workspace = _infer_workspace(source_path)
    cfg = load_config(workspace)
    _merge_pack_vault_config(cfg, workspace)
    text = source_path.read_text(errors="replace", encoding="utf-8")

    max_tier = getattr(args, "tier", None)
    if max_tier is None:
        max_tier = cfg.get("render", {}).get("default_tier", 3) or 3

    # Render with the directive/skip collectors (the --explain path), so we can
    # attribute tokens to each resolved directive and report tier-skipped ones.
    _directives: list = []
    _skipped: list = []
    _stats = {"directive_count": 0, "cache_hits": 0, "cache_misses": 0}
    rendered = render_source(text, cfg, workspace, max_tier=max_tier,
                             _directive_collector=_directives,
                             _stats=_stats,
                             _skipped_directives=_skipped,
                             no_cache=getattr(args, "no_cache", False))

    total_tokens = estimate_tokens(rendered)
    total_bytes = len(rendered.encode("utf-8", errors="replace"))

    def _pct(n):
        return round(100.0 * n / total_tokens, 1) if total_tokens else 0.0

    # Per-directive breakdown in document (collector) order. Volatile fields
    # (duration_ms, cached) are intentionally dropped so the report is diffable.
    directives = []
    for d in _directives:
        # #606 review: nested records (inside an @include) are already covered
        # by the include's own depth-0 record — counting both double-counts
        # the include's contents and pushes the pct sum past 100%.
        if d.get("depth", 0) > 0:
            continue
        out = d.get("output") or ""
        tok = estimate_tokens(out)
        directives.append({
            "name": d.get("name", ""),
            "args": d.get("args", ""),
            "tokens": tok,
            "pct": _pct(tok),
        })

    # Per-section breakdown by markdown heading; text before the first heading
    # is the "(preamble)".
    heading_re = _re.compile(r"^(#{1,6})\s+(.*)$")
    sections = []
    state = {"heading": "(preamble)", "lines": []}

    def _flush():
        if not state["lines"]:
            return
        body = "\n".join(state["lines"])
        tok = estimate_tokens(body)
        if state["heading"] == "(preamble)" and tok == 0:
            return
        sections.append({"heading": state["heading"], "tokens": tok, "pct": _pct(tok)})

    for line in rendered.splitlines():
        m = heading_re.match(line)
        if m:
            _flush()
            state = {"heading": m.group(2).strip() or "#", "lines": [line]}
        else:
            state["lines"].append(line)
    _flush()

    skipped = [{"name": str(s.get("name", "")).lstrip("@"), "tier": s.get("tier"),
                "args": s.get("args", "")} for s in _skipped]

    report = {
        "source": source_path.name,
        "tier": max_tier,
        "total_tokens": total_tokens,
        "total_bytes": total_bytes,
        "directive_count": len(directives),
        "skipped_count": len(skipped),
        "directives": directives,
        "sections": sections,
        "skipped": skipped,
    }

    if getattr(args, "json", False):
        print(_json.dumps(report, indent=2, default=str))
        return 0

    # Human-readable, deterministic table.
    print(f"perseus preview: {source_path.name} (tier {max_tier})")
    print(f"total: {total_tokens} tokens, {total_bytes} bytes, "
          f"{len(directives)} directive(s), {len(skipped)} skipped")

    if directives:
        print("\nBy directive (document order):")
        for d in directives:
            arg = str(d["args"])
            if len(arg) > 40:
                arg = arg[:39] + "…"
            arg = (" " + arg) if arg else ""
            print(f"  {d['tokens']:>6}  {d['pct']:>5}%  @{d['name']}{arg}")

    if sections:
        print("\nBy section:")
        for s in sections:
            h = s["heading"]
            if len(h) > 50:
                h = h[:49] + "…"
            print(f"  {s['tokens']:>6}  {s['pct']:>5}%  {h}")

    if skipped:
        print(f"\nSkipped (tier > {max_tier}):")
        for s in skipped:
            print(f"  @{s['name']} (tier {s['tier']})")

    return 0


def cmd_warmup(args, cfg):
    """Pre-populate the render cache for a context file without writing output."""
    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        print(f"Error: file not found: {source_path}", file=sys.stderr)
        sys.exit(1)

    workspace = _infer_workspace(source_path)
    cfg = load_config(workspace)
    text = source_path.read_text(errors="replace", encoding="utf-8")

    _stats = {"directive_count": 0, "cache_hits": 0, "cache_misses": 0}
    render_source(text, cfg, workspace, _stats=_stats)

    total_dirs = _stats["directive_count"]
    cached = _stats["cache_hits"] + _stats["cache_misses"]
    if cached > 0:
        print(f"Warmup complete: {total_dirs} directives, "
              f"{_stats['cache_hits']} cached, {_stats['cache_misses']} newly cached")
    else:
        print(f"Warmup complete: {total_dirs} directives resolved (no @cache directives found)")


class WatchTarget(NamedTuple):
    """One watched source/output render pair."""
    name: str
    source: Path
    output: Path


def _watch_rel(path: Path, workspace: Path) -> str:
    try:
        return str(path.relative_to(workspace))
    except ValueError:
        return str(path)


def _watch_target_key(target: WatchTarget) -> tuple[str, str]:
    return (str(target.source), str(target.output))


def _watch_interval_s(args, cfg) -> tuple[float | None, str | None]:
    raw = getattr(args, "interval", None)
    if raw is None:
        raw = (cfg.get("watch") or {}).get("poll_interval_s", 5)
    try:
        interval = float(raw)
    except (TypeError, ValueError):
        return None, f"watch interval must be a number, got {raw!r}"
    if interval <= 0:
        return None, "watch interval must be greater than zero"
    return interval, None


def _watch_resolve_ref(ref: str, workspace: Path, cfg: dict, allow_arg: bool) -> tuple[Path, str | None]:
    allow = allow_arg or bool(cfg.get("render", {}).get("allow_outside_workspace", False))
    path, warning = _resolve_path(ref, workspace, allow_outside_workspace=allow)
    if warning:
        return path, warning.replace("> ⚠ ", "")
    return path, None


def _watch_target_from_refs(
    name: str,
    source_ref: str,
    output_ref: str,
    workspace: Path,
    cfg: dict,
    allow_arg: bool,
) -> tuple[WatchTarget | None, list[str]]:
    errors: list[str] = []
    source, source_error = _watch_resolve_ref(source_ref, workspace, cfg, allow_arg)
    output, output_error = _watch_resolve_ref(output_ref, workspace, cfg, allow_arg)
    if source_error:
        errors.append(f"{name}: source {source_error}")
    if output_error:
        errors.append(f"{name}: output {output_error}")
    if errors:
        return None, errors
    return WatchTarget(name=name, source=source, output=output), []


def _watch_targets_from_pack(
    workspace: Path,
    manifest: str | None,
    cfg: dict,
    allow_arg: bool,
) -> tuple[list[WatchTarget], list[str]]:
    result = validate_context_pack(workspace, manifest)
    if not result.get("valid", False):
        errors = result.get("errors") or ["context pack is invalid"]
        return [], [f"context pack {err}" for err in errors]
    targets: list[WatchTarget] = []
    errors: list[str] = []
    for idx, render in enumerate(result.get("renders", []), start=1):
        name = str(render.get("name") or f"render-{idx}")
        source_ref = render.get("source")
        output_ref = render.get("output")
        if not isinstance(source_ref, str) or not source_ref:
            errors.append(f"{name}: source is required")
            continue
        if not isinstance(output_ref, str) or not output_ref:
            errors.append(f"{name}: output is required")
            continue
        target, target_errors = _watch_target_from_refs(name, source_ref, output_ref, workspace, cfg, allow_arg)
        if target:
            targets.append(target)
        errors.extend(target_errors)
    if not targets and not errors:
        errors.append("context pack has no render targets")
    return targets, errors


def _watch_targets_from_args(args, cfg, workspace: Path) -> tuple[list[WatchTarget], list[str]]:
    allow_arg = bool(getattr(args, "allow_outside_workspace", False))
    source_arg = getattr(args, "source", None)
    output_arg = getattr(args, "output", None)
    manifest_arg = getattr(args, "manifest", None)
    explicit_single = bool(source_arg or output_arg)
    pack_path = _pack_manifest_path(workspace, manifest_arg)
    if not explicit_single and (manifest_arg or pack_path.exists()):
        return _watch_targets_from_pack(workspace, manifest_arg, cfg, allow_arg)

    source_ref = source_arg or ".perseus/context.md"
    output_ref = output_arg or ".hermes.md"
    target, errors = _watch_target_from_refs("default", source_ref, output_ref, workspace, cfg, allow_arg)
    return ([target] if target else []), errors


def _watch_target_mtime(target: WatchTarget, getmtime: Callable[[Path], float]) -> float | None:
    try:
        return float(getmtime(target.source))
    except OSError:
        return None


def _watch_render_target(target: WatchTarget, cfg: dict, render_fn: Callable) -> None:
    render_args = argparse.Namespace(source=str(target.source), output=str(target.output))
    try:
        render_fn(render_args, cfg)
    except SystemExit as exc:
        code = exc.code if isinstance(exc.code, int) else 1
        raise RuntimeError(f"render exited with status {code}") from None


def _watch_render_and_record(
    target: WatchTarget,
    cfg: dict,
    workspace: Path,
    last_rendered: dict[tuple[str, str], float | None],
    pending: dict[tuple[str, str], float | None],
    getmtime: Callable[[Path], float],
    render_fn: Callable,
    log_stream,
    exit_on_error: bool,
) -> bool:
    key = _watch_target_key(target)
    try:
        _watch_render_target(target, cfg, render_fn)
    except Exception as exc:
        print(f"[watch] render error: {exc}", file=log_stream)
        last_rendered[key] = _watch_target_mtime(target, getmtime)
        pending.pop(key, None)
        return not exit_on_error

    last_rendered[key] = _watch_target_mtime(target, getmtime)
    pending.pop(key, None)
    print(
        f"[watch] rendered -> {_watch_rel(target.output, workspace)} "
        f"(changed: {_watch_rel(target.source, workspace)})",
        file=log_stream,
    )
    return True


def _watch_loop(
    targets: list[WatchTarget],
    cfg: dict,
    workspace: Path,
    interval_s: float,
    *,
    exit_on_error: bool = False,
    getmtime: Callable[[Path], float] = os.path.getmtime,
    sleep: Callable[[float], None] = time.sleep,
    render_fn: Callable = cmd_render,
    should_stop: Callable[[], bool] | None = None,
    log_stream=None,
    max_cycles: int | None = None,
) -> int:
    log_stream = log_stream or sys.stderr
    should_stop = should_stop or (lambda: False)
    last_rendered: dict[tuple[str, str], float | None] = {}
    pending: dict[tuple[str, str], float | None] = {}

    try:
        for target in targets:
            ok = _watch_render_and_record(
                target, cfg, workspace, last_rendered, pending,
                getmtime, render_fn, log_stream, exit_on_error,
            )
            if not ok:
                return 1

        cycles = 0
        while True:
            if should_stop():
                print("[watch] stopped", file=log_stream)
                return 0
            if max_cycles is not None and cycles >= max_cycles:
                return 0
            sleep(interval_s)
            cycles += 1
            if should_stop():
                print("[watch] stopped", file=log_stream)
                return 0

            for target in targets:
                key = _watch_target_key(target)
                current = _watch_target_mtime(target, getmtime)
                if current == last_rendered.get(key):
                    pending.pop(key, None)
                    continue
                if key in pending and pending[key] == current:
                    ok = _watch_render_and_record(
                        target, cfg, workspace, last_rendered, pending,
                        getmtime, render_fn, log_stream, exit_on_error,
                    )
                    if not ok:
                        return 1
                else:
                    pending[key] = current
    except KeyboardInterrupt:
        print("[watch] stopped", file=log_stream)
        return 0


def _watch_install_signal_handlers() -> tuple[dict, dict]:
    state = {"stop": False, "signal": None}
    previous = {}

    def _handler(signum, _frame):
        state["stop"] = True
        try:
            state["signal"] = signal.Signals(signum).name
        except Exception:
            state["signal"] = str(signum)

    for sig in (signal.SIGINT, signal.SIGTERM):
        previous[sig] = signal.getsignal(sig)
        signal.signal(sig, _handler)
    return state, previous


def _watch_restore_signal_handlers(previous: dict) -> None:
    for sig, handler in previous.items():
        signal.signal(sig, handler)


def cmd_watch(args, cfg) -> int:
    workspace = Path(args.workspace).expanduser().resolve() if getattr(args, "workspace", None) else Path.cwd().resolve()
    cfg = load_config(workspace)
    interval_s, interval_error = _watch_interval_s(args, cfg)
    if interval_error:
        print(f"perseus watch: {interval_error}", file=sys.stderr)
        return 1

    targets, errors = _watch_targets_from_args(args, cfg, workspace)
    if errors:
        for err in errors:
            print(f"perseus watch: {err}", file=sys.stderr)
        return 1
    if not targets:
        print("perseus watch: no render targets", file=sys.stderr)
        return 1

    signal_state, previous_handlers = _watch_install_signal_handlers()
    try:
        return _watch_loop(
            targets,
            cfg,
            workspace,
            interval_s or 5,
            exit_on_error=bool(getattr(args, "exit_on_error", False)),
            should_stop=lambda: bool(signal_state["stop"]),
        )
    finally:
        _watch_restore_signal_handlers(previous_handlers)


def cmd_graph(args, cfg) -> int:
    """Print a static directive dependency graph."""
    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        print(f"Error: file not found: {source_path}", file=sys.stderr)
        return 1
    workspace = Path(args.workspace).expanduser().resolve() if getattr(args, "workspace", None) else _infer_workspace(source_path)
    cfg = load_config(workspace)
    # task-65: ensure plugin directives are visible in the graph
    register_plugins(cfg)
    graph = directive_dependency_graph(
        source_path.read_text(errors="replace", encoding="utf-8"),
        source_name=str(source_path),
        workspace=workspace,
    )
    if getattr(args, "json", False):
        print(json.dumps(graph, indent=2))
        return 0

    print(f"Directive graph: {source_path}")
    print(f"Nodes: {graph['summary']['node_count']}  Edges: {graph['summary']['edge_count']}")
    for node in graph["nodes"]:
        flags = []
        meta = node["metadata"]
        if meta["executes_shell"]:
            flags.append("shell")
        if meta["reads_files"]:
            flags.append("files")
        if meta["mutates_state"]:
            flags.append("mutates")
        if meta["cacheable"]:
            flags.append("cacheable")
        flag_text = f" [{' '.join(flags)}]" if flags else ""
        resources = ", ".join(f"{r['kind']}={r['value']}" for r in node["resources"])
        resource_text = f" -> {resources}" if resources else ""
        print(f"- {node['id']} line {node['line']}: {node['directive']} ({node['kind']}){flag_text}{resource_text}")
    return 0


def cmd_prefetch(args, cfg) -> int:
    """Run configured prefetch rules against a static directive graph."""
    source_path = Path(args.source).expanduser().resolve()
    if not source_path.exists():
        print(f"Error: file not found: {source_path}", file=sys.stderr)
        return 1
    workspace = Path(args.workspace).expanduser().resolve() if getattr(args, "workspace", None) else _infer_workspace(source_path)
    cfg = load_config(workspace)
    # task-65: register plugin directives so prefetch graph rules can target them
    register_plugins(cfg)
    result = prefetch_source(
        source_path.read_text(errors="replace", encoding="utf-8"),
        cfg,
        workspace=workspace,
        source_name=str(source_path),
    )
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2))
    else:
        print(format_prefetch_human(result))
    return 1 if result["summary"]["failed"] else 0



